/* DAWAH X — ahmad, অধ্যায় 87 · খণ্ড 87 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][87]=[[17201,17201,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ تَمْرًا فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ لَهُ طَهُورٌ ‏","","",""],[17202,17202,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ بِمَاءٍ فَإِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[17203,17203,"","","‏ ‏وَقَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17204,17204,"","","‏ ‏وَقَالَ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَعَلَى ‏ ‏ذِي الرَّحِمِ ‏ ‏اثْنَتَانِ ‏ ‏صِلَةٌ ‏ ‏وَصَدَقَةٌ ‏","","",""],[17205,17205,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17206,17206,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏وَحَبِيبٌ ‏ ‏وَيُونُسُ ‏ ‏وَقَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17207,17207,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ تَمْرًا فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ لَهُ طَهُورٌ ‏","","",""],[17208,17208,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏لَمْ يَذْكُرْ ‏ ‏أَيُّوبُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَنْ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17209,17209,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَقَتَادَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17210,17210,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ أُمِّ الرَّائِحِ بِنْتِ صُلَيْعٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَهِيَ عَلَى ‏ ‏ذِي الْقُرْبَى ‏ ‏ثِنْتَانِ صِلَةٌ ‏ ‏وَصَدَقَةٌ ‏","","",""],[17211,17211,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرِ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَالصَّدَقَةُ ‏ ‏عَلَى ‏ ‏ذِي الرَّحِمِ ‏ ‏اثْنَتَانِ ‏ ‏صَدَقَةٌ ‏ ‏وَصِلَةٌ ‏","","",""],[17212,17212,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏وَسَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ الدَّمَ ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏يَقُولُ ‏ ‏إِنْ لَمْ يَكُنْ ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى ‏ ‏حَلْقَ الرَّأْسِ فَلَا أَدْرِي مَا هُوَ ‏","","",""],[17213,17213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ الدَّمَ ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[17214,17214,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ وَجَدَ تَمْرًا فَلْيُفْطِرْ عَلَيْهِ فَإِنْ لَمْ يَجِدْ تَمْرًا فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[17215,17215,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدِ بْنِ أَبِي فَضَالَةَ الْأَنْصَارِيِّ ‏ ‏وَكَانَ مِنْ الصَّحَابَةِ أَنَّهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا جَمَعَ اللَّهُ الْأَوَّلِينَ وَالْآخِرِينَ لِيَوْمٍ لَا ‏ ‏رَيْبَ ‏ ‏فِيهِ نَادَى مُنَادٍ مَنْ كَانَ أَشْرَكَ فِي عَمَلٍ عَمِلَهُ لِلَّهِ عَزَّ وَجَلَّ أَحَدًا فَلْيَطْلُبْ ثَوَابَهُ مِنْ عِنْدِ غَيْرِ اللَّهِ فَإِنَّ اللَّهَ أَغْنَى الشُّرَكَاءِ عَنْ الشِّرْكِ ‏","","",""],[17216,17216,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏أَبِي رَمْلَةَ ‏ ‏قَالَ حَدَّثَنَاهُ ‏ ‏مِخْنَفُ بْنُ سُلَيْمٍ ‏ ‏قَالَ ‏ ‏وَنَحْنُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ وَاقِفٌ ‏ ‏بِعَرَفَاتٍ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ عَلَى كُلِّ أَهْلِ بَيْتٍ ‏ ‏أَوْ عَلَى كُلِّ أَهْلِ بَيْتٍ ‏ ‏فِي كُلِّ عَامٍ ‏ ‏أَضْحَاةً ‏ ‏وَعَتِيرَةً ‏ ‏قَالَ تَدْرُونَ مَا ‏ ‏الْعَتِيرَةُ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَلَا أَدْرِي مَا رَدُّوا ‏ ‏قَالَ هَذِهِ الَّتِي يَقُولُ النَّاسُ ‏ ‏الرَّجَبِيَّةُ ‏","","",""],[17217,17217,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ عَلِيٍّ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي الدِّيلِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ الظُّهْرَ فِي بَيْتِي ثُمَّ خَرَجْتُ ‏ ‏بِأَبَاعِرَ ‏ ‏لِي ‏ ‏لِأُصْدِرَهَا ‏ ‏إِلَى الرَّاعِي فَمَرَرْتُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِالنَّاسِ الظُّهْرَ فَمَضَيْتُ فَلَمْ أُصَلِّ مَعَهُ فَلَمَّا أَصْدَرْتُ ‏ ‏أَبَاعِرِي ‏ ‏وَرَجَعْتُ ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏مَا مَنَعَكَ يَا فُلَانُ أَنْ تُصَلِّيَ مَعَنَا حِينَ مَرَرْتَ بِنَا قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي قَدْ كُنْتُ صَلَّيْتُ فِي بَيْتِي قَالَ وَإِنْ ‏","","",""],[17218,17218,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ بْنِ الْمُطَّلِبِ بْنِ عَبْدِ مَنَافٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏وُلِدْتُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفِيلِ فَنَحْنُ ‏ ‏لِدَانِ ‏ ‏وُلِدْنَا مَوْلِدًا وَاحِدًا ‏","","",""],[17219,17219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِي ‏ ‏النَّجْمِ ‏ ‏وَسَجَدَ النَّاسُ مَعَهُ ‏ ‏قَالَ ‏ ‏الْمُطَّلِبُ ‏ ‏وَلَمْ أَسْجُدْ مَعَهُمْ وَهُوَ يَوْمَئِذٍ مُشْرِكٌ ‏ ‏قَالَ ‏ ‏الْمُطَّلِبُّ ‏ ‏فَلَا أَدَعُ السُّجُودَ فِيهَا أَبَدًا ‏","","",""],[17220,17220,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏سُورَةَ ‏ ‏النَّجْمِ ‏ ‏فَسَجَدَ وَسَجَدَ مَنْ عِنْدَهُ فَرَفَعْتُ رَأْسِي وَأَبَيْتُ أَنْ أَسْجُدَ ‏ ‏وَلَمْ ‏ ‏يَكُنْ أَسْلَمَ يَوْمَئِذٍ ‏ ‏الْمُطَّلِبُ ‏ ‏وَكَانَ بَعْدَ ذَلِكَ لَا يَسْمَعُ أَحَدًا يَقْرَأُ بِهَا إِلَّا سَجَدَ مَعَهُ ‏","","",""],[17221,17221,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَمِيرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ النَّاسِ نَفْسُ مُسْلِمٍ يَقْبِضُهَا اللَّهُ عَزَّ وَجَلَّ تُحِبُّ أَنْ تَعُودَ إِلَيْكُمْ وَأَنَّ لَهَا الدُّنْيَا وَمَا فِيهَا غَيْرُ الشَّهِيدِ ‏ ‏و قَالَ ‏ ‏ابْنُ أَبِي عَمِيرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ أُقْتَلَ فِي سَبِيلِ اللَّهِ أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي ‏ ‏الْمَدَرُ ‏ ‏وَالْوَبَرُ ‏","","",""],[17222,17222,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمِيرَةَ الْأَزْدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذَكَرَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَقَالَ ‏ ‏اللَّهُمَّ اجْعَلْهُ هَادِيًا مَهْدِيًّا وَاهْدِ بِهِ ‏","","",""],[17223,17223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالُ بْنُ أَبِي حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏نَظَرَ ‏ ‏عُمَرُ ‏ ‏إِلَى ‏ ‏أَبِي عَبْدِ الْحَمِيدِ ‏ ‏أَوْ ‏ ‏ابْنِ عَبْدِ الْحَمِيدِ ‏ ‏شَكَّ ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَكَانَ اسْمُهُ ‏ ‏مُحَمَّدًا ‏ ‏وَرَجُلٌ يَقُولُ لَهُ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَعَلَ اللَّهُ بِكَ وَفَعَلَ وَفَعَلَ قَالَ وَجَعَلَ يَسُبُّهُ قَالَ فَقَالَ أَمِيرُ الْمُؤْمِنِينَ عِنْدَ ذَلِكَ يَا ‏ ‏ابْنَ زَيْدٍ ‏ ‏ادْنُ مِنِّي قَالَ أَلَا أَرَى ‏ ‏مُحَمَّدًا ‏ ‏يُسَبُّ بِكَ لَا وَاللَّهِ لَا ‏ ‏تُدْعَى ‏ ‏مُحَمَّدًا ‏ ‏مَا دُمْتُ حَيًّا فَسَمَّاهُ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏ثُمَّ أَرْسَلَ إِلَى ‏ ‏بَنِي طَلْحَةَ ‏ ‏لِيُغَيِّرَ أَهْلُهُمْ أَسْمَاءَهُمْ وَهُمْ يَوْمَئِذٍ سَبْعَةٌ وَسَيِّدُهُمْ وَأَكْبَرُهُمْ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ فَقَالَ ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ يَا أَمِيرَ الْمُؤْمِنِينَ فَوَاللَّهِ ‏ ‏إِنْ سَمَّانِي ‏ ‏مُحَمَّدًا ‏ ‏يَعْنِي إِلَّا ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏قُومُوا لَا سَبِيلَ لِي إِلَى شَيْءٍ سَمَّاهُ ‏ ‏مُحَمَّدٌ ‏","","",""],[17224,17224,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ حَالَ الشَّيْطَانُ بَيْنِي وَبَيْنَ صَلَاتِي وَبَيْنَ قِرَاءَتِي قَالَ ‏ ‏ذَاكَ شَيْطَانٌ يُقَالُ لَهُ ‏ ‏خَنْزَبٌ فَإِذَا أَنْتَ حَسَسْتَهُ فَتَعَوَّذْ بِاللَّهِ مِنْهُ وَاتْفُلْ عَنْ يَسَارِكَ ثَلَاثًا ‏ ‏قَالَ ‏ ‏فَفَعَلْتُ ذَاكَ فَأَذْهَبَهُ اللَّهُ عَزَّ وَجَلَّ عَنِّي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَن ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَن ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَن ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ حَالَ الشَّيْطَانُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[17225,17225,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ طَلْحَةَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ ‏ ‏يَؤُمَّ ‏ ‏قَوْمَهُ قَالَ ثُمَّ قَالَ ‏ ‏مَنْ ‏ ‏أَمَّ ‏ ‏قَوْمًا فَلْيُخَفِّفْ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَالْمَرِيضَ وَذَا الْحَاجَةِ فَإِذَا صَلَّى وَحْدَهُ فَلْيُصَلِّ كَيْفَ شَاءَ ‏","","",""],[17226,17226,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَن ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏فِي يَوْمِ جُمُعَةٍ لِنَعْرِضَ عَلَيْهِ مُصْحَفًا لَنَا عَلَى مُصْحَفِهِ فَلَمَّا حَضَرَتْ الْجُمُعَةُ أَمَرَنَا فَاغْتَسَلْنَا ثُمَّ أُتِينَا بِطِيبٍ فَتَطَيَّبْنَا ثُمَّ جِئْنَا الْمَسْجِدَ فَجَلَسْنَا إِلَى رَجُلٍ فَحَدَّثَنَا عَنْ ‏ ‏الدَّجَّالِ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏فَقُمْنَا إِلَيْهِ فَجَلَسْنَا فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَكُونُ لِلْمُسْلِمِينَ ثَلَاثَةُ ‏ ‏أَمْصَارٍ ‏ ‏مِصْرٌ ‏ ‏بِمُلْتَقَى الْبَحْرَيْنِ ‏ ‏وَمِصْرٌ ‏ ‏بِالْحِيرَةِ ‏ ‏وَمِصْرٌ ‏ ‏بِالشَّامِ ‏ ‏فَيَفْزَعُ النَّاسُ ثَلَاثَ فَزَعَاتٍ فَيَخْرُجُ ‏ ‏الدَّجَّالُ ‏ ‏فِي أَعْرَاضِ النَّاسِ فَيَهْزِمُ مَنْ قِبَلَ الْمَشْرِقِ فَأَوَّلُ ‏ ‏مِصْرٍ ‏ ‏يَرِدُهُ ‏ ‏الْمِصْرُ ‏ ‏الَّذِي بِمُلْتَقَى الْبَحْرَيْنِ فَيَصِيرُ أَهْلُهُ ثَلَاثَ فِرَقٍ فِرْقَةٌ تَقُولُ ‏ ‏نُشَامُّهُ ‏ ‏نَنْظُرُ مَا هُوَ وَفِرْقَةٌ تَلْحَقُ ‏ ‏بالْأَعْرَابِ ‏ ‏وَفِرْقَةٌ تَلْحَقُ ‏ ‏بِالْمِصْرِ ‏ ‏الَّذِي ‏ ‏يَلِيهِمْ وَمَعَ ‏ ‏الدَّجَّالِ ‏ ‏سَبْعُونَ أَلْفًا عَلَيْهِمْ ‏ ‏السِّيجَانُ ‏ ‏وَأَكْثَرُ تَبَعِهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنِّسَاءُ ثُمَّ يَأْتِي ‏ ‏الْمِصْرَ ‏ ‏الَّذِي يَلِيهِ فَيَصِيرُ أَهْلُهُ ثَلَاثَ فِرَقٍ فِرْقَةٌ تَقُولُ ‏ ‏نُشَامُّهُ ‏ ‏وَنَنْظُرُ مَا هُوَ ‏ ‏وَفِرْقَةٌ تَلْحَقُ ‏ ‏بالْأَعْرَابِ ‏ ‏وَفِرْقَةٌ تَلْحَقُ ‏ ‏بِالْمِصْرِ ‏ ‏الَّذِي ‏ ‏يَلِيهِمْ بِغَرْبِيِّ ‏ ‏الشَّامِ ‏ ‏وَيَنْحَازُ الْمُسْلِمُونَ إِلَى ‏ ‏عَقَبَةِ أَفِيقٍ ‏ ‏فَيَبْعَثُونَ ‏ ‏سَرْحًا ‏ ‏لَهُمْ فَيُصَابُ ‏ ‏سَرْحُهُمْ ‏ ‏فَيَشْتَدُّ ذَلِكَ عَلَيْهِمْ وَتُصِيبُهُمْ مَجَاعَةٌ شَدِيدَةٌ ‏ ‏وَجَهْدٌ ‏ ‏شَدِيدٌ حَتَّى إِنَّ أَحَدَهُمْ لَيُحْرِقُ ‏ ‏وَتَرَ ‏ ‏قَوْسِهِ فَيَأْكُلُهُ فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ نَادَى مُنَادٍ مِنْ السَّحَرِ يَا أَيُّهَا النَّاسُ أَتَاكُمْ ‏ ‏الْغَوْثُ ‏ ‏ثَلَاثًا فَيَقُولُ بَعْضُهُمْ لِبَعْضٍ إِنَّ هَذَا لَصَوْتُ رَجُلٍ شَبْعَانَ وَيَنْزِلُ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عِنْدَ صَلَاةِ الْفَجْرِ فَيَقُولُ لَهُ أَمِيرُهُمْ رُوحَ اللَّهِ تَقَدَّمْ صَلِّ فَيَقُولُ هَذِهِ الْأُمَّةُ أُمَرَاءُ بَعْضُهُمْ عَلَى بَعْضٍ فَيَتَقَدَّمُ أَمِيرُهُمْ فَيُصَلِّي فَإِذَا قَضَى صَلَاتَهُ أَخَذَ ‏ ‏عِيسَى ‏ ‏حَرْبَتَهُ فَيَذْهَبُ نَحْوَ ‏ ‏الدَّجَّالِ ‏ ‏فَإِذَا رَآهُ ‏ ‏الدَّجَّالُ ‏ ‏ذَابَ كَمَا يَذُوبُ الرَّصَاصُ فَيَضَعُ حَرْبَتَهُ بَيْنَ ‏ ‏ثَنْدُوَتِهِ ‏ ‏فَيَقْتُلُهُ وَيَنْهَزِمُ أَصْحَابُهُ فَلَيْسَ يَوْمَئِذٍ شَيْءٌ يُوَارِي مِنْهُمْ أَحَدًا حَتَّى إِنَّ الشَّجَرَةَ لَتَقُولُ يَا مُؤْمِنُ هَذَا كَافِرٌ وَيَقُولُ الْحَجَرُ يَا مُؤْمِنُ هَذَا كَافِرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏لِنَعْرِضَ عَلَيْهِ مُصْحَفًا لَنَا عَلَى مُصْحَفِهِ فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَلَيْسَ شَيْءٌ يَوْمَئِذٍ يَجُنُّ مِنْهُمْ أَحَدًا وَقَالَ ذَابَ كَمَا يَذُوبُ الرَّصَاصُ ‏","","",""],[17227,17227,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏أَنَّ ‏ ‏مُطَرِّفًا ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي عَامِرِ بْنِ صَعْصَعَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ الثَّقَفِيَّ ‏ ‏دَعَا لَهُ بِلَبَنٍ لِيَسْقِيَهُ قَالَ ‏ ‏مُطَرِّفٌ ‏ ‏إِنِّي صَائِمٌ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏مِنْ النَّارِ ‏ ‏كَجُنَّةِ ‏ ‏أَحَدِكُمْ مِنْ الْقِتَالِ وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ صِيَامٌ حَسَنٌ ثَلَاثَةُ أَيَّامٍ مِنْ الشَّهْرِ ‏","","",""],[17228,17228,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يُنَادِي كُلَّ لَيْلَةٍ سَاعَةً فِيهَا مُنَادٍ ‏ ‏هَلْ مِنْ دَاعٍ فَأَسْتَجِيبَ لَهُ هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ ‏","","",""],[17229,17229,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَن ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَن ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏وَامْرَأَةٍ مِنْ قَيْسٍ ‏ ‏أَنَّهُمَا سَمِعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحَدُهُمَا سَمِعْتُهُ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي ذَنْبِي خَطَئِي وَعَمْدِي اللَّهُمَّ إِنِّي ‏ ‏أَسْتَهْدِيكَ لِأَرْشَدِ أَمْرِي وَأَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي ‏","","",""],[17230,17230,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَن ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَن ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ اجْعَلْنِي إِمَامَ قَوْمِي قَالَ ‏ ‏اقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا ‏","","",""],[17231,17231,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ الْمَدِينِيَّ ‏ ‏أَخْبَرَنِي ‏ ‏يَزِيدُ يَعْنِي ابْنَ خُصَيْفَةَ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ كَعْبٍ السُّلَمِيِّ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ أَخَذَهُ وَجَعٌ قَدْ كَادَ يُبْطِلُهُ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَزَعَمَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏ضَعْ يَمِينَكَ عَلَى مَكَانِكَ الَّذِي ‏ ‏تَشْتَكِي فَامْسَحْ بِهَا سَبْعَ مَرَّاتٍ وَقُلْ أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ فِي كُلِّ مَسْحَةٍ ‏","","",""],[17232,17232,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ ‏ ‏عَن ‏ ‏ابْنِ إِسْحَاقَ يَعْنِي مُحَمَّدًا ‏ ‏عَنْ ‏ ‏عُبَيِدِ اللَّهِ ‏ ‏أَوْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ طَلْحَةَ بْنِ كَرِيزٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏دُعِيَ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏إِلَى ‏ ‏خِتَانٍ ‏ ‏فَأَبَى أَنْ يُجِيبَ فَقِيلَ لَهُ فَقَالَ إِنَّا ‏ ‏كُنَّا لَا نَأْتِي ‏ ‏الْخِتَانَ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏نُدْعَى لَهُ ‏","","",""],[17233,17233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَن ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَن ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏فَأَمَرَ لِي بِلَبَنِ ‏ ‏لِقْحَةٍ ‏ ‏فَقُلْتُ إِنِّي صَائِمٌ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏مِنْ عَذَابِ اللَّهِ ‏ ‏كَجُنَّةِ ‏ ‏أَحَدِكُمْ مِنْ الْقِتَالِ وَصِيَامٌ حَسَنٌ ثَلَاثَةُ أَيَّامٍ مِنْ كُلِّ شَهْرٍ قَالَ وَكَانَ آخِرُ شَيْءٍ عَهِدَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ أَنْ قَالَ ‏ ‏جَوِّزْ ‏ ‏فِي صَلَاتِكَ وَاقْدُرْ النَّاسَ بِأَضْعَفِهِمْ فَإِنَّ مِنْهُمْ الصَّغِيرَ وَالْكَبِيرَ وَالضَّعِيفَ وَذَا الْحَاجَةِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَن ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَن ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[17234,17234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَامِرٍ ‏ ‏اسْتَعْمَلَ ‏ ‏كِلَابَ بْنَ أُمَيَّةَ ‏ ‏عَلَى ‏ ‏الَأَيْلَةِ ‏ ‏وَعُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏فِي أَرْضِهِ فَأَتَاهُ ‏ ‏عُثْمَانُ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ يَقُولُ ‏ ‏إِنَّ فِي اللَّيْلِ سَاعَةً تُفْتَحُ فِيهَا أَبْوَابُ السَّمَاءِ ‏ ‏يُنَادِي مُنَادٍ ‏ ‏هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ دَاعٍ فَأَسْتَجِيبَ لَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ ‏ ‏قَالَا جَمِيعًا ‏ ‏وَإِنَّ ‏ ‏دَاوُدَ ‏ ‏خَرَجَ ذَاتَ لَيْلَةٍ فَقَالَ لَا يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ أَحَدٌ شَيْئًا إِلَّا أَعْطَاهُ إِلَّا أَنْ يَكُونَ سَاحِرًا أَوْ ‏ ‏عَشَّارًا ‏ ‏فَدَعَا ‏ ‏كِلَابٌ ‏ ‏بِقُرْقُورٍ ‏ ‏فَرَكِبَ فِيهِ وَانْحَدَرَ إِلَى ‏ ‏ابْنِ عَامِرٍ ‏ ‏فَقَالَ دُونَكَ عَمَلَكَ قَالَ لِمَ قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏بِكَذَا وَكَذَا ‏","","",""],[17235,17235,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏أَنَّ ‏ ‏وَفْدَ ثَقِيفٍ ‏ ‏قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَهُمْ الْمَسْجِدَ لِيَكُونَ أَرَقَّ لِقُلُوبِهِمْ فَاشْتَرَطُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا ‏ ‏يُحْشَرُوا ‏ ‏وَلَا ‏ ‏يُعْشَرُوا ‏ ‏وَلَا ‏ ‏يُجَبُّوا ‏ ‏وَلَا يُسْتَعْمَلَ عَلَيْهِمْ غَيْرُهُمْ قَالَ فَقَالَ ‏ ‏إِنَّ لَكُمْ أَنْ لَا ‏ ‏تُحْشَرُوا ‏ ‏وَلَا ‏ ‏تُعْشَرُوا ‏ ‏وَلَا يُسْتَعْمَلَ عَلَيْكُمْ غَيْرُكُمْ وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا خَيْرَ فِي دِينٍ لَا رُكُوعَ فِيهِ قَالَ وَقَالَ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏يَا رَسُولَ اللَّهِ عَلِّمْنِي الْقُرْآنَ وَاجْعَلْنِي إِمَامَ قَوْمِي ‏","","",""],[17236,17236,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي عَاصِمٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏أَنَّ آخِرَ مَا فَارَقَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّيْتَ بِقَوْمٍ فَخَفِّفْ بِهِمْ حَتَّى وَقَّتَ لِي ‏ ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ‏","","",""],[17237,17237,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُنَادِي كُلَّ لَيْلَةٍ مُنَادٍ ‏ ‏هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ هَلْ مِنْ دَاعٍ فَأَسْتَجِيبَ لَهُ ‏","","",""],[17238,17238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خُثَيْمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ أَبِي عَاصِمٍ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏أَنَّ آخِرَ كَلَامٍ كَلَّمَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ اسْتَعْمَلَنِي عَلَى ‏ ‏الطَّائِفِ ‏ ‏فَقَالَ ‏ ‏خَفِّفْ الصَّلَاةَ عَلَى النَّاسِ حَتَّى وَقَّتَ لِي ‏ ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ‏ ‏وَأَشْبَاهَهَا مِنْ الْقُرْآنِ ‏","","",""],[17239,17239,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ بْنِ يَعْلَى الطَّائِفِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَكَمِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏يَقُولُ ‏ ‏اسْتَعْمَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الطَّائِفِ ‏ ‏وَكَانَ آخِرُ مَا عَهِدَهُ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَفِّفْ عَلَى النَّاسِ الصَّلَاةَ ‏","","",""],[17240,17240,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هُرَيْمٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا إِذْ ‏ ‏شَخَصَ ‏ ‏بِبَصَرِهِ ثُمَّ ‏ ‏صَوَّبَهُ ‏ ‏حَتَّى كَادَ أَنْ يُلْزِقَهُ بِالْأَرْضِ قَالَ ثُمَّ ‏ ‏شَخَصَ ‏ ‏بِبَصَرِهِ فَقَالَ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَأَمَرَنِي أَنْ أَضَعَ هَذِهِ الْآيَةَ بِهَذَا الْمَوْضِعِ مِنْ هَذِهِ السُّورَةِ ‏ { ‏إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنْ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ ‏}","","",""],[17241,17241,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏ذَكَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا قَالَ ‏ ‏وَذَاكَ عِنْدَ ‏ ‏أَوَانِ ‏ ‏ذَهَابِ الْعِلْمِ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ يَذْهَبُ الْعِلْمُ وَنَحْنُ نَقْرَأُ ‏ ‏الْقُرْآنَ وَنُقْرِئُهُ أَبْنَاءَنَا وَيُقْرِئُهُ أَبْنَاؤُنَا أَبْنَاءَهُمْ إِلَى يَوْمِ الْقِيَامَةِ قَالَ ‏ ‏ثَكِلَتْكَ ‏ ‏أُمُّكَ يَا ‏ ‏ابْنَ أُمِّ لَبِيدٍ ‏ ‏إِنْ كُنْتُ لَأَرَاكَ مِنْ أَفْقَهِ رَجُلٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَوَلَيْسَ هَذِهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏يَقْرَءُونَ التَّوْرَاةَ وَالْإِنْجِيلَ فَلَا يَنْتَفِعُونَ مِمَّا فِيهِمَا بِشَيْءٍ ‏","","",""],[17242,17242,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ لَبِيدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا أَوَانُ ذَهَابِ الْعِلْمِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ هَذَا أَوَانُ انْقِطَاعِ الْعِلْمِ ‏ ‏فَقُلْتُ وَكَيْفَ وَفِينَا كِتَابُ اللَّهِ نُعَلِّمُهُ أَبْنَاءَنَا وَيُعَلِّمُهُ أَبْنَاؤُنَا أَبْنَاءَهُمْ قَالَ ثَكِلَتْكَ أُمُّكَ ‏ ‏ابْنَ لَبِيدٍ ‏ ‏مَا كُنْتُ أَحْسَبُكَ إِلَّا مِنْ أَعْقَلِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَلَيْسَ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏فِيهِمْ كِتَابُ اللَّهِ تَعَالَى ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ أَلَيْسَ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏فِيهِمْ التَّوْرَاةُ وَالْإِنْجِيلُ ‏ ‏ثُمَّ لَمْ يَنْتَفِعُوا مِنْهُ بِشَيْءٍ ‏ ‏أَوْ قَالَ أَلَيْسَ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏أَوْ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏شُعْبَةُ ‏ ‏يَقُولُ ذَلِك فِيهِمْ كِتَابُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[17243,17243,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏آخَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ رَجُلَيْنِ فَقُتِلَ أَحَدُهُمَا وَمَاتَ الْآخَرُ بَعْدَهُ فَصَلَّيْنَا عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُلْتُمْ قَالُوا دَعَوْنَا لَهُ اللَّهُمَّ أَلْحِقْهُ بِصَاحِبِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَيْنَ صَلَاتُهُ بَعْدَ صَلَاتِهِ وَأَيْنَ صَوْمُهُ بَعْدَ صَوْمِهِ وَأَيْنَ عَمَلُهُ بَعْدَ عَمَلِهِ ‏ ‏شَكَّ فِي الصَّلَاةِ وَالْعَمَلِ ‏ ‏شُعْبَةُ ‏ ‏فِي أَحَدِهِمَا ‏ ‏الَّذِي بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبِيعَةَ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ آخَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ رَجُلَيْنِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17244,17244,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏قَالَ ‏ ‏آخَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ رَجُلَيْنِ فَقُتِلَ أَحَدُهُمَا وَمَاتَ الْآخَرُ بَعْدَهُ فَصَلَّيْنَا عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُلْتُمْ قَالُوا دَعَوْنَا لَهُ أَنْ يَغْفِرَ لَهُ وَأَنْ يَرْحَمَهُ وَأَنْ يُلْحِقَهُ بِصَاحِبِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَيْنَ صَلَاتُهُ بَعْدَ صَلَاتِهِ وَعَمَلُهُ بَعْدَ عَمَلِهِ أَوْ صِيَامُهُ بَعْدَ صِيَامِهِ قَالَ إِنَّ مَا بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[17245,17245,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏أَوْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَوْتُ الْفَجْأَةِ أَخْذَةُ أَسَفٍ ‏ ‏وَحَدَّثَ ‏ ‏بِهِ مَرَّةً عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17246,17246,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَوْتِ الْفَجْأَةِ ‏ ‏أَخْذَةُ أَسَفٍ ‏","","",""],[17247,17247,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏مُعَاذِ بْنِ عَفْرَاءَ الْقُرَشِيِّ ‏ ‏أَنَّهُ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏مَعَ ‏ ‏مُعَاذِ ابْنِ عَفْرَاءَ ‏ ‏بَعْدَ الْعَصْرِ ‏ ‏أَوْ بَعْدَ الصُّبْحِ ‏ ‏فَلَمْ يُصَلِّ فَسَأَلْتُهُ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاتَيْنِ بَعْدَ الْغَدَاةِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏","","",""],[17248,17248,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏نَصْرَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏مُعَاذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّهُ طَافَ مَعَ ‏ ‏مُعَاذِ ابْنِ عَفْرَاءَ ‏ ‏فَلَمْ يُصَلِّ بَعْدَ الْعَصْرِ ‏ ‏أَوْ ‏ ‏بَعْدَ الصُّبْحِ ‏ ‏فَقَالَ مَا يَمْنَعُكَ أَنْ تُصَلِّيَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى ‏ ‏أَوْ يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏","","",""],[17249,17249,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ثَابِتِ ابْنِ وَدِيعَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا أَتَاهُ بِضِبَابٍ قَدْ ‏ ‏احْتَرَشَهَا ‏ ‏فَجَعَلَ يَنْظُرُ إِلَى ضَبٍّ مِنْهَا ثُمَّ قَالَ إِنَّ أُمَّةً ‏ ‏مُسِخَتْ ‏ ‏فَلَا أَدْرِي لَعَلَّ هَذَا مِنْهَا ‏","","",""],[17250,17250,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ثَابِتِ ابْنِ وَدِيعَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضِبَابٍ قَدْ ‏ ‏احْتَرَشَهَا ‏ ‏قَالَ ‏ ‏فَجَعَلَ يَنْظُرُ إِلَيْهِ وَيُقَلِّبُهُ وَقَالَ إِنَّ أُمَّةً ‏ ‏مُسِخَتْ ‏ ‏فَلَا ‏ ‏يُدْرَى مَا فَعَلَتْ وَإِنِّي لَا أَدْرِي لَعَلَّ هَذَا مِنْهَا ‏","","",""],[17251,17251,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ ابْنِ وَدِيعَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏بَنِي فَزَارَةَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضِبَابٍ قَالَ ‏ ‏فَجَعَلَ يُقَلِّبُ ضَبًّا مِنْهَا بَيْنَ يَدَيْهِ فَقَالَ إِنَّ أُمَّةً ‏ ‏مُسِخَتْ ‏ ‏قَالَ وَأَكْثَرُ عِلْمِي أَنَّهُ قَالَ مَا أَدْرِي لَعَلَّ هَذَا مِنْهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ شَيْئًا نَحْوًا مِنْ هَذَا قَالَ فَلَمْ يَأْمُرْهُ وَلَمْ يَنْهَ أَحَدًا عَنْهُ ‏","","",""],[17252,17252,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ يَزِيدَ ابْنِ وَدَاعَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏اصْطَدْنَا ضِبَابًا وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ مَغَازِيهِ قَالَ فَطَبَخَ النَّاسُ وَشَوَوْا قَالَ ‏ ‏فَأَخَذْتُ ضَبًّا فَشَوَيْتُهُ فَأَتَيْتُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَهُ بَيْنَ يَدَيْهِ فَأَخَذَ عُودًا فَجَعَلَ يُقَلِّبُ بِهِ أَصَابِعَهُ ‏ ‏أَوْ يَعُدُّهَا ‏ ‏ثُمَّ قَالَ إِنَّ أُمَّةً مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُسِخَتْ ‏ ‏دَوَابَّ فِي الْأَرْضِ وَإِنِّي لَا أَدْرِي أَيَّ الدَّوَابِّ هِيَ قَالَ قُلْتُ إِنَّ النَّاسَ قَدْ شَوَوْا قَالَ فَلَمْ يَأْكُلْ مِنْهُ وَلَمْ يَنْهَهُمْ عَنْهُ ‏","","",""],[17253,17253,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ ابْنِ وَدِيعَةَ ‏ ‏قَالَ إِنَّهُ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضَبٍّ فَقَالَ أُمَّةٌ ‏ ‏مُسِخَتْ ‏ ‏وَاللَّهُ أَعْلَمُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَاللَّهُ أَعْلَمُ ‏","","",""],[17254,17254,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏سَمَّاهُ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ النَّحَّامِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ مُؤَذِّنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لَيْلَةٍ بَارِدَةٍ وَأَنَا فِي لِحَافِي فَتَمَنَّيْتُ أَنْ يَقُولَ صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏فَلَمَّا بَلَغَ حَيَّ عَلَى الْفَلَاحِ قَالَ ‏ ‏صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏ثُمَّ سَأَلْتُ عَنْهَا فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَمَرَهُ بِذَلِكَ ‏","","",""],[17255,17255,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ النَّحَّامِ ‏ ‏قَالَ ‏ ‏نُودِيَ بِالصُّبْحِ فِي يَوْمٍ بَارِدٍ وَأَنَا فِي ‏ ‏مِرْطِ ‏ ‏امْرَأَتِي فَقُلْتُ لَيْتَ الْمُنَادِيَ قَالَ مَنْ قَعَدَ فَلَا حَرَجَ عَلَيْهِ ‏ ‏فَنَادَى مُنَادِي النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آخِرِ أَذَانِهِ وَمَنْ قَعَدَ فَلَا حَرَجَ عَلَيْهِ ‏","","",""],[17256,17256,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ الْوَلِيدُ بْنُ أَبِي الْوَلِيدِ الْمَدَنِيُّ ‏ ‏أَنَّ ‏ ‏عِمْرَانَ بْنَ أَبِي أَنَسٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي خِرَاشٍ السُّلَمِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ هَجَرَ أَخَاهُ سَنَةً فَهُوَ ‏ ‏كَسَفْكِ ‏ ‏دَمِهِ ‏","","",""],[17257,17257,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏وَحَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَدِيٍّ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَلَغَهُ مَعْرُوفٌ عَنْ أَخِيهِ مِنْ غَيْرِ مَسْأَلَةٍ وَلَا إِشْرَافِ نَفْسٍ فَلْيَقْبَلْهُ وَلَا يَرُدَّهُ فَإِنَّمَا هُوَ رِزْقٌ سَاقَهُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ ‏","","",""],[17258,17258,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ الْمُنْذِرِ بْنِ أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي أُسَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَارِثَ بْنَ زِيَادٍ صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْأَنْصَارَ ‏ ‏أَحَبَّهُ اللَّهُ حِينَ يَلْقَاهُ وَمَنْ أَبْغَضَ ‏ ‏الْأَنْصَارَ ‏ ‏أَبْغَضَهُ اللَّهُ حِينَ يَلْقَاهُ ‏","","",""],[17259,17259,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرِ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي لَاسٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏حَمَلَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِبِلٍ مِنْ إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏لِلْحَجِّ فَقُلْنَا يَا رَسُولَ اللَّهِ مَا نَرَى أَنْ تَحْمِلَنَا هَذِهِ قَالَ ‏ ‏مَا مِنْ بَعِيرٍ لَنَا إِلَّا فِي ‏ ‏ذُرْوَتِهِ ‏ ‏شَيْطَانٌ فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا إِذَا رَكِبْتُمُوهَا كَمَا أَمَرْتُكُمْ ثُمَّ ‏ ‏امْتَهِنُوهَا ‏ ‏لِأَنْفُسِكُمْ فَإِنَّمَا يَحْمِلُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[17260,17260,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏وَكَانَ ثِقَةً ‏ ‏عَنِ ‏ ‏أَبُو لَاسٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏حَمَلَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِبِلٍ مِنْ إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏ضِعَافٍ إِلَى الْحَجِّ قَالَ فَقُلْنَا لَهُ يَا رَسُولَ اللَّهِ إِنَّ هَذِهِ الْإِبِلَ ضِعَافٌ ‏ ‏نَخْشَى أَنْ لَا تَحْمِلَنَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ بَعِيرٍ إِلَّا فِي ‏ ‏ذُرْوَتِهِ ‏ ‏شَيْطَانٌ فَارْكَبُوهُنَّ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِنَّ كَمَا أُمِرْتُمْ ثُمَّ ‏ ‏امْتَهِنُوهُنَّ ‏ ‏لِأَنْفُسِكُمْ فَإِنَّمَا يَحْمِلُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[17261,17261,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْخُذَنَّ أَحَدُكُمْ مَتَاعَ صَاحِبِهِ جَادًّا وَلَا لَاعِبًا وَإِذَا وَجَدَ أَحَدُكُمْ عَصَا صَاحِبِهِ فَلْيَرْدُدْهَا عَلَيْهِ ‏","","",""],[17262,17262,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْخُذَنَّ أَحَدُكُمْ مَتَاعَ صَاحِبِهِ لَعِبًا جَادًّا وَإِذَا أَخَذَ أَحَدُكُمْ عَصَا أَخِيهِ فَلْيَرْدُدْهَا عَلَيْهِ ‏","","",""],[17263,17263,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْخُذَنَّ أَحَدُكُمْ مَتَاعَ صَاحِبِهِ لَعِبًا جَادًّا وَإِذَا أَخَذَ أَحَدُكُمْ عَصَا أَخِيهِ فَلْيَرْدُدْهَا عَلَيْهِ ‏","","",""],[17264,17264,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ هَاشِمِ بْنِ عُتْبَةَ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا دَعَا فَرَفَعَ يَدَيْهِ مَسَحَ وَجْهَهُ بِيَدَيْهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَقَدْ خَالَفُوا ‏ ‏قُتَيْبَةَ ‏ ‏فِي إِسْنَادِ هَذَا الْحَدِيثِ وَأَحْسِبُ ‏ ‏قُتَيْبَةَ ‏ ‏وَهِمَ فِيهِ يَقُولُونَ عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ أَبِيهِ ‏","","",""],[17265,17265,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏مَجْمَعُ بْنُ يَعْقُوبَ ‏ ‏مِنْ أَهْلِ ‏ ‏قُبَاءَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ ‏ ‏أَنَّ بَعْضَ أَهْلِهِ قَالَ لِجَدِّهِ مِنْ قِبَلِ أُمِّهِ وَهُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي حَبِيبَةَ ‏ ‏مَا أَدْرَكْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَانَا فِي مَسْجِدِنَا هَذَا فَجِئْتُ فَجَلَسْتُ إِلَى جَنْبِهِ ‏ ‏فَأُتِيَ بِشَرَابٍ فَشَرِبَ ثُمَّ نَاوَلَنِي وَأَنَا عَنْ يَمِينِهِ قَالَ وَرَأَيْتُهُ يَوْمَئِذٍ صَلَّى فِي نَعْلَيْهِ وَأَنَا يَوْمَئِذٍ غُلَامٌ ‏","","",""],[17266,17266,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏الشَّرِيدِ ‏ ‏أَنَّ أُمَّهُ أَوْصَتْ أَنْ يُعْتِقَ عَنْهَا رَقَبَةً مُؤْمِنَةً فَسَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ عِنْدِي جَارِيَةٌ سَوْدَاءُ ‏ ‏أَوْ ‏ ‏نُوبِيَّةٌ ‏ ‏فَأَعْتِقُهَا فَقَالَ ائْتِ بِهَا فَدَعَوْتُهَا فَجَاءَتْ فَقَالَ لَهَا مَنْ رَبُّكِ قَالَتْ اللَّهُ قَالَ مَنْ أَنَا فَقَالَتْ أَنْتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ ‏","","",""],[17267,17267,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏وَبْرُ بْنُ أَبِي دُلَيْلَةَ ‏ ‏شَيْخٌ مِنْ أَهْلِ ‏ ‏الطَّائِفِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مَيْمُونِ بْنِ مُسَيْكَةَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُّ ‏ ‏الْوَاجِدِ ‏ ‏يُحِلُّ ‏ ‏عِرْضَهُ وَعُقُوبَتَهُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏عِرْضُهُ ‏ ‏شِكَايَتُهُ وَعُقُوبَتُهُ حَبْسُهُ ‏","","",""],[17268,17268,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَارٌ لِخَدِيجَةَ بِنْتِ خُوَيْلِدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏لِخَدِيجَةَ ‏ ‏أَيْ ‏ ‏خَدِيجَةُ ‏ ‏وَاللَّهِ ‏ ‏لَا أَعْبُدُ ‏ ‏اللَّاتَ ‏ ‏وَالْعُزَّى ‏ ‏وَاللَّهِ لَا أَعْبُدُ أَبَدًا قَالَ فَتَقُولُ ‏ ‏خَدِيجَةُ ‏ ‏خَلِّ ‏ ‏اللَّاتَ ‏ ‏خَلِّ ‏ ‏الْعُزَّى ‏ ‏قَالَ كَانَتْ صَنَمَهُمْ الَّتِي كَانُوا يَعْبُدُونَ ثُمَّ يَضْطَجِعُونَ ‏","","",""],[17269,17269,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏صَفْوَانَ بْنَ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏يَعْلَى ‏ ‏كَانَ يَقُولُ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏لَيْتَنِي أَرَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ يُنْزَلُ عَلَيْهِ قَالَ فَلَمَّا كَانَ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏وَعَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَوْبٌ قَدْ أُظِلَّ بِهِ مَعَهُ نَاسٌ مِنْ أَصْحَابِهِ مِنْهُمْ ‏ ‏عُمَرُ ‏ ‏إِذْ جَاءَهُ رَجُلٌ عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏مُتَضَمِّخًا ‏ ‏بِطِيبٍ قَالَ فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ ‏ ‏تَرَى فِي رَجُلٍ أَحْرَمَ بِعُمْرَةٍ فِي ‏ ‏جُبَّةٍ ‏ ‏بَعْدَ مَا ‏ ‏تَضَمَّخَ ‏ ‏بِطِيبٍ فَنَظَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاعَةً ثُمَّ سَكَتَ فَجَاءَهُ الْوَحْيُ فَأَشَارَ ‏ ‏عُمَرُ ‏ ‏إِلَى ‏ ‏يَعْلَى ‏ ‏أَنْ تَعَالَ فَجَاءَ ‏ ‏يَعْلَى ‏ ‏فَأَدْخَلَ رَأْسَهُ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحْمَرُّ الْوَجْهِ كَذَلِكَ سَاعَةً ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَقَالَ أَيْنَ الَّذِي سَأَلَنِي عَنْ الْعُمْرَةِ ‏ ‏آنِفًا ‏ ‏فَالْتُمِسَ ‏ ‏الرَّجُلُ فَأُتِيَ بِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا الطِّيبُ الَّذِي بِكَ فَاغْسِلْهُ ثَلَاثَ مَرَّاتٍ وَأَمَّا ‏ ‏الْجُبَّةُ ‏ ‏فَانْزِعْهَا ثُمَّ اصْنَعْ فِي عُمْرَتِكَ كَمَا تَصْنَعُ فِي حَجَّتِكَ ‏","","",""],[17270,17270,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏صَفْوَانُ بْنُ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَاتَلَ أَجِيرِي رَجُلًا فَعَضَّ يَدَهُ فَنَزَعَ يَدَهُ مِنْ ‏ ‏فِيهِ ‏ ‏فَأَنْدَرَ ‏ ‏ثَنِيَّتَهُ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَهْدَرَهُ ‏ ‏وَقَالَ ‏ ‏فَيَدَعُ يَدَهُ فِي ‏ ‏فِيكَ ‏ ‏تَقْضِمُهَا ‏ ‏كَمَا ‏ ‏يَقْضِمُ ‏ ‏الْفَحْلُ ‏","","",""],[17271,17271,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَتْكَ رُسُلِي فَأَعْطِهِمْ ‏ ‏أَوْ قَالَ فَادْفَعْ إِلَيْهِمْ ‏ ‏ثَلَاثِينَ دِرْعًا وَثَلَاثِينَ بَعِيرًا أَوْ أَقَلَّ مِنْ ذَلِكَ فَقَالَ لَهُ الْعَارِيَةُ ‏ ‏مُؤَدَّاةٌ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ ‏","","",""],[17272,17272,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏عَنْ ‏ ‏بَعْضِ بَنِي يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَاسْتَلَمَ الرُّكْنَ قَالَ ‏ ‏يَعْلَى ‏ ‏وَكُنْتُ مِمَّا ‏ ‏يَلِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا بَلَغْتُ الرُّكْنَ الْغَرْبِيَّ الَّذِي ‏ ‏يَلِي الْأَسْوَدَ ‏ ‏وَحَدَرْتُ ‏ ‏بَيْنَ يَدَيْهِ لِأَسْتَلِمَ فَقَالَ مَا شَأْنُكَ قُلْتُ أَلَا تَسْتَلِمُ هَذَيْنِ قَالَ ‏ ‏أَلَمْ تَطُفْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ بَلَى قَالَ أَرَأَيْتَهُ يَسْتَلِمُ هَذَيْنِ ‏ ‏يَعْنِي الْغَرْبِيَّيْنِ ‏ ‏قُلْتُ لَا قَالَ فَلَيْسَ لَكَ فِيهِ أُسْوَةٌ حَسَنَةٌ قُلْتُ بَلَى قَالَ فَانْفُذْ عَنْكَ ‏","","",""],[17273,17273,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏ابْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏يَعْلَى ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُضْطَبِعًا ‏ ‏بِرِدَاءٍ ‏ ‏حَضْرَمِيٍّ ‏","","",""],[17274,17274,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏عَمَّيْهِ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏وَسَلَمَةَ بْنِ أُمَيَّةَ ‏ ‏قَالَا ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏مَعَنَا صَاحِبٌ لَنَا فَاقْتَتَلَ هُوَ وَرَجُلٌ مِنْ الْمُسْلِمِينَ فَعَضَّ ذَلِكَ الرَّجُلُ بِذِرَاعِهِ ‏ ‏فَاجْتَبَذَ ‏ ‏يَدَهُ مِنْ ‏ ‏فِيهِ ‏ ‏فَطَرَحَ ‏ ‏ثَنِيَّتَهُ ‏ ‏فَذَهَبَ الرَّجُلُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ ‏ ‏الْعَقْلَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْطَلِقُ أَحَدُكُمْ إِلَى أَخِيهِ يَعَضُّهُ عَضِيضَ ‏ ‏الْفَحْلِ ‏ ‏ثُمَّ يَأْتِي يَلْتَمِسُ ‏ ‏الْعَقْلَ ‏ ‏لَا ‏ ‏دِيَةَ ‏ ‏لَكَ قَالَ فَأَطَلَّهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي فَأَبْطَلَهَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنِ ‏ ‏ابْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏يَعْلَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ ‏ ‏فِي الَّذِي يُعَضُّ أَحَدُهُمَا ‏","","",""],[17275,17275,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ هَارُونَ الْبَلْخِيُّ أَبُو حَفْصٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏بَعْضِ بَنِي يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُضْطَبِعًا ‏ ‏بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏بِبُرْدٍ ‏ ‏لَهُ نَجْرَانِيٍّ ‏","","",""],[17276,17276,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَهُوَ ‏ ‏مُضْطَبِعٌ ‏ ‏بِبُرْدٍ ‏ ‏لَهُ ‏ ‏حَضْرَمِيٍّ ‏","","",""],[17277,17277,"","","‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَشِيرُ بْنُ طَلْحَةَ أَبُو نَصْرٍ الْحَضْرَمِيُّ ‏ ‏أَوْ ‏ ‏الْخُشَنِيُّ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ دُرَيْكٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُنِي فِي ‏ ‏سَرَايَا ‏ ‏فَبَعَثَنِي ذَاتَ يَوْمٍ فِي ‏ ‏سَرِيَّةٍ ‏ ‏وَكَانَ رَجُلٌ يَرْكَبُ ‏ ‏بَغْلًا ‏ ‏فَقُلْتُ لَهُ ارْحَلْ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ بَعَثَنِي فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَقَالَ مَا أَنَا بِخَارِجٍ مَعَكَ قُلْتُ وَلِمَ قَالَ حَتَّى تَجْعَلَ لِي ثَلَاثَةَ دَنَانِيرَ قُلْتُ الْآنَ حَيْثُ وَدَّعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنَا بِرَاجِعٍ إِلَيْهِ ارْحَلْ وَلَكَ ثَلَاثَةُ دَنَانِيرَ فَلَمَّا رَجَعْتُ مِنْ ‏ ‏غَزَاتِي ‏ ‏ذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَيْسَ لَهُ مِنْ ‏ ‏غَزَاتِهِ ‏ ‏هَذِهِ وَمِنْ دُنْيَاهُ وَمِنْ آخِرَتِهِ إِلَّا ثَلَاثَةُ الدَّنَانِيرِ ‏","","",""],[17278,17278,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ بْنِ أُمَيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏يَعْلَى ‏ ‏قَالَ ‏ ‏جِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي أُمَيَّةُ ‏ ‏يَوْمَ الْفَتْحِ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏بَايِعْ ‏ ‏أَبِي عَلَى الْهِجْرَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ ‏ ‏أُبَايِعُهُ ‏ ‏عَلَى الْجِهَادِ فَقَدْ انْقَطَعَتْ الْهِجْرَةُ ‏","","",""],[17279,17279,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أُمَيَّةَ بْنِ أَبِي عُثْمَانَ الْقُرَشِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُيَيِّ بْنِ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏يَعْلَى ‏ ‏يُصَلِّي قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَالَ لَهُ رَجُلٌ ‏ ‏أَوْ قِيلَ لَهُ ‏ ‏أَنْتَ رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُصَلِّي قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ قَالَ ‏ ‏يَعْلَى ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ ‏ ‏قَالَ ‏ ‏لَهُ ‏ ‏يَعْلَى ‏ ‏فَأَنْ تَطْلُعَ الشَّمْسُ وَأَنْتَ فِي أَمْرِ اللَّهِ خَيْرٌ مِنْ أَنْ تَطْلُعَ وَأَنْتَ ‏ ‏لَاهٍ ‏","","",""],[17280,17280,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أُمَيَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حُيَيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَفْوَانُ بْنُ يَعْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَحْرُ هُوَ جَهَنَّمُ قَالُوا ‏ ‏لِيَعْلَى ‏ ‏فَقَالَ أَلَا تَرَوْنَ أَنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏نَارًا أَحَاطَ بِهِمْ ‏ ‏سُرَادِقُهَا ‏ } ‏قَالَ ‏ ‏لَا وَالَّذِي نَفْسُ ‏ ‏يَعْلَى ‏ ‏بِيَدِهِ لَا أَدْخُلُهَا أَبَدًا حَتَّى أُعْرَضَ عَلَى اللَّهِ عَزَّ وَجَلَّ وَلَا يُصِيبُنِي مِنْهَا قَطْرَةٌ حَتَّى أَلْقَى اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[17281,17281,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقْرَأُ ‏ { ‏وَنَادَوْا يَا مَالِكُ ‏}","","",""],[17282,17282,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ بْنِ أُمَيَّةَ ابْنِ أَخِي يَعْلَى بْنِ أُمَيَّةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏يَعْلَى بْنَ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏جِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَبِي يَوْمَ الْفَتْحِ فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ ‏ ‏بَايِعْ ‏ ‏أَبِي عَلَى الْهِجْرَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ ‏ ‏أُبَايِعُهُ ‏ ‏عَلَى الْجِهَادِ وَقَدْ انْقَطَعَتْ الْهِجْرَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏بِإِسْنَادٍ مِثْلَهُ ‏","","",""],[17283,17283,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏وَعَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏وَعَلَيْهِ ‏ ‏رَدْعٌ ‏ ‏مِنْ ‏ ‏زَعْفَرَانٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَحْرَمْتُ فِيمَا ‏ ‏تَرَى وَالنَّاسُ يَسْخَرُونَ مِنِّي ‏ ‏وَأَطْرَقَ ‏ ‏هُنَيْهَةً ‏ ‏قَالَ ثُمَّ دَعَاهُ فَقَالَ ‏ ‏اخْلَعْ عَنْكَ هَذِهِ ‏ ‏الْجُبَّةَ ‏ ‏وَاغْسِلْ عَنْكَ هَذَا ‏ ‏الزَّعْفَرَانَ ‏ ‏وَاصْنَعْ فِي عُمْرَتِكَ كَمَا تَصْنَعُ فِي حَجِّكَ ‏","","",""],[17284,17284,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُتَضَمِّخٌ ‏ ‏بِخَلُوقٍ وَعَلَيْهِ مُقَطَّعَاتٌ فَقَالَ أَهْلَلْتُ بِعُمْرَةٍ قَالَ انْزِعْ هَذِهِ وَاغْتَسِلْ وَاصْنَعْ فِي عُمْرَتِكَ مَا تَصْنَعُ فِي حَجِّكَ ‏","","",""],[17285,17285,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشَ ‏ ‏الْعُسْرَةِ ‏ ‏وَكَانَ مِنْ أَوْثَقِ أَعْمَالِي فِي نَفْسِي وَكَانَ لِي أَجِيرٌ فَقَاتَلَ إِنْسَانًا فَعَضَّ أَحَدُهُمَا صَاحِبَهُ فَانْتَزَعَ أُصْبُعَهُ ‏ ‏فَأَنْدَرَ ‏ ‏ثَنِيَّتَهُ ‏ ‏وَقَالَ أَفَيَدَعُ يَدَهُ فِي ‏ ‏فِيكَ تَقْضِمُهَا ‏ ‏قَالَ أَحْسَبُهُ كَمَا يَقْضِمُ ‏ ‏الْفَحْلُ ‏","","",""],[17286,17286,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏أَنَّهُ كَانَ مَعَ ‏ ‏عُمَرَ ‏ ‏فِي سَفَرٍ وَأَنَّهُ طَلَبَ إِلَى ‏ ‏عُمَرَ ‏ ‏أَنْ يُرِيَهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُزِّلَ عَلَيْهِ قَالَ فَبَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَعَلَيْهِ سِتْرٌ مَسْتُورٌ مِنْ الشَّمْسِ إِذْ أَتَاهُ رَجُلٌ عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏وَعَلَيْهَا ‏ ‏رَدْعٌ ‏ ‏مِنْ ‏ ‏زَعْفَرَانٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَحْرَمْتُ بِعُمْرَةٍ وَإِنَّ النَّاسَ يَسْخَرُونَ مِنِّي فَكَيْفَ أَصْنَعُ قَالَ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُجِبْهُ فَبَيْنَا هُوَ كَذَلِكَ إِذْ ‏ ‏أَوْمَأَ ‏ ‏إِلَيَّ ‏ ‏عُمَرُ ‏ ‏بِيَدِهِ فَأَدْخَلْتُ رَأْسِي مَعَهُمْ فِي السِّتْرِ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحْمَرٌّ وَجْنَتَاهُ لَهُ ‏ ‏غَطِيطٌ ‏ ‏سَاعَةً ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَجَلَسَ فَقَالَ أَيْنَ السَّائِلُ عَنْ الْعُمْرَةِ فَقَامَ إِلَيْهِ الرَّجُلُ فَقَالَ ‏ ‏انْزِعْ ‏ ‏جُبَّتَكَ ‏ ‏هَذِهِ عَنْكَ وَمَا كُنْتَ صَانِعًا فِي حَجِّكَ إِذَا أَحْرَمْتَ فَاصْنَعْهُ فِي عُمْرَتِكَ ‏","","",""],[17287,17287,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الْحَيَاءَ وَالسَّتْرَ ‏","","",""],[17288,17288,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَهُوَ ‏ ‏مُضْطَبِعٌ ‏ ‏بِبُرْدٍ ‏ ‏لَهُ ‏ ‏حَضْرَمِيٍّ ‏","","",""],[17289,17289,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ يَعْلَى بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏حَيِيٌّ ‏ ‏سِتِّيرٌ ‏ ‏فَإِذَا أَرَادَ أَحَدُكُمْ أَنْ يَغْتَسِلَ ‏ ‏فَلْيَتَوَارَ ‏ ‏بِشَيْءٍ ‏","","",""],[17290,17290,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقَطَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَحَدَّثَنِي ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الْخَطْمِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَارَةُ بْنُ خُزَيْمَةَ ‏ ‏والْحَارِثُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجًّا فَرَأَيْتُهُ ‏ ‏خَرَجَ مِنْ الْخَلَاءِ فَاتَّبَعْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏أَوْ الْقَدَحِ ‏ ‏فَجَلَسْتُ لَهُ بِالطَّرِيقِ وَكَانَ إِذَا أَتَى حَاجَتَهُ أَبْعَدَ ‏","","",""],[17291,17291,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنَى ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَدِيٍّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏رَجُلَيْنِ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّهُمَا أَتَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلَانِهِ مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَقَلَّبَ فِيهِمَا الْبَصَرَ وَرَآهُمَا ‏ ‏جَلْدَيْنِ ‏ ‏فَقَالَ ‏ ‏إِنْ شِئْتُمَا أَعْطَيْتُكُمَا وَلَا حَظَّ فِيهَا لِغَنِيٍّ وَلَا لِقَوِيٍّ مُكْتَسِبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلَانِ ‏ ‏أَنَّهُمَا أَتَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ قَالَ فَصَعَّدَ فِيهِمَا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17292,17292,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏سِنَانِ بْنِ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ذُؤَيْبًا أَبَا قَبِيصَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَبْعَثُ ‏ ‏بِالْبُدْنِ ‏ ‏فَيَقُولُ ‏ ‏إِنْ ‏ ‏عَطِبَ ‏ ‏مِنْهَا شَيْءٌ فَخَشِيتَ عَلَيْهِ فَانْحَرْهَا ‏ ‏وَاغْمِسْ ‏ ‏نَعْلَهَا فِي دَمِهَا وَاضْرِبْ ‏ ‏صَفْحَتَهَا ‏ ‏وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ رُفْقَتِكَ ‏","","",""],[17293,17293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ذُؤَيْبًا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ مَعَهُ بِبَدَنَتَيْنِ ‏ ‏وَأَمَرَهُ إِنْ عَرَضَ لَهُمَا شَيْءٌ أَوْ ‏ ‏عَطْبَةٌ ‏ ‏أَنْ يَنْحَرَهُمَا ثُمَّ ‏ ‏يَغْمِسَ ‏ ‏نِعَالَهُمَا فِي دِمَائِهِمَا ثُمَّ يَضْرِبَ بِنَعْلِ كُلِّ وَاحِدَةٍ ‏ ‏صَفْحَتَهَا ‏ ‏وَيُخْلِيَهُمَا ‏ ‏لِلنَّاسِ وَلَا يَأْكُلَ مِنْهَا هُوَ وَلَا أَحَدٌ مِنْ أَصْحَابِهِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَكَانَ يَقُولُ مُرْسَلٌ ‏ ‏يَعْنِي ‏ ‏مَعْمَرًا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏ثُمَّ كَتَبْتُهُ لَهُ مِنْ كِتَابِ ‏ ‏سَعِيدٍ ‏ ‏فَأَعْطَيْتُهُ فَنَظَرَ فَقَرَأَهُ فَقَالَ نَعَمْ وَلَكِنِّي أَهَابُ إِذَا لَمْ أَنْظُرْ فِي الْكِتَابِ ‏","","",""],[17294,17294,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ غُنْدَرٌ ‏ ‏وَيَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏مُحَمَّدَ بْنَ مَسْلَمَةَ ‏ ‏يُطَارِدُ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُرِيدُ أَنْ يَنْظُرَ إِلَيْهَا ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏بُثَيْنَةَ ابْنَةَ الضَّحَّاكِ ‏ ‏يُرِيدُ أَنْ يَنْظُرَ إِلَيْهَا ‏ ‏فَقُلْتُ أَنْتَ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَفْعَلُ هَذَا قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَلْقَى اللَّهُ عَزَّ وَجَلَّ فِي قَلْبِ امْرِئٍ خِطْبَةَ امْرَأَةٍ فَلَا بَأْسَ أَنْ يَنْظُرَ إِلَيْهَا ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏مُحَمَّدَ بْنَ مَسْلَمَةَ ‏ ‏يُطَارِدُ ‏ ‏بُثَيْنَةَ ابْنَةَ الضَّحَّاكِ ‏ ‏أُخْتَ ‏ ‏أَبِي جَبِيرَةَ بْنِ الضَّحَّاكِ ‏ ‏وَهِيَ عَلَى ‏ ‏إِجَّارٍ لَهُمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17295,17295,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ هَلْ سَمِعَ أَحَدٌ مِنْكُمْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا شَيْئًا فَقَامَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَقَالَ شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْضِي لَهَا بِالسُّدُسِ فَقَالَ هَلْ سَمِعَ ذَلِكَ مَعَكَ أَحَدٌ فَقَامَ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏فَقَالَ شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْضِي لَهَا بِالسُّدُسِ فَأَعْطَاهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏السُّدُسَ ‏","","",""],[17296,17296,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَهْلُ بْنُ أَبِي الصَّلْتِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏عَلِيًّا ‏ ‏بَعَثَ إِلَى ‏ ‏مُحَمَّدِ بْنِ مَسْلَمَةَ ‏ ‏فَجِيءَ بِهِ فَقَالَ مَا خَلَّفَكَ عَنْ هَذَا الْأَمْرِ قَالَ دَفَعَ إِلَيَّ ابْنُ عَمِّكَ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيْفًا فَقَالَ ‏ ‏قَاتِلْ بِهِ مَا قُوتِلَ الْعَدُوُّ فَإِذَا رَأَيْتَ النَّاسَ يَقْتُلُ بَعْضُهُمْ بَعْضًا فَاعْمَدْ بِهِ إِلَى صَخْرَةٍ فَاضْرِبْهُ بِهَا ثُمَّ الْزَمْ بَيْتَكَ حَتَّى تَأْتِيَكَ ‏ ‏مَنِيَّةٌ ‏ ‏قَاضِيَةٌ ‏ ‏أَوْ يَدٌ خَاطِئَةٌ قَالَ ‏ ‏خَلُّوا ‏ ‏عَنْهُ ‏","","",""],[17297,17297,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ يَعْنِي الرَّازِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ خَرَشَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ خَرَشَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُصْعَبٌ الزُّبَيْرِيُّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏مِثْلَهُ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ بْنُ إِسْحَاقَ بْنِ خَرَشَةَ ‏ ‏مِنْ ‏ ‏بَنِي عَامِرِ بْنِ لُؤَيٍّ ‏ ‏وَلَمْ يُسْنِدْهُ عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَحَدٌ إِلَّا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ الْجَدَّةُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏تَسْأَلُهُ مِيرَاثَهَا فَقَالَ مَا أَعْلَمُ لَكِ فِي كِتَابِ اللَّهِ شَيْئًا وَلَا أَعْلَمُ لَكِ فِي سُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ شَيْءٍ حَتَّى أَسْأَلَ النَّاسَ فَسَأَلَ فَقَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ لَهَا السُّدُسَ فَقَالَ مَنْ يَشْهَدُ مَعَكَ ‏ ‏أَوْ مَنْ يَعْلَمُ مَعَكَ ‏ ‏فَقَامَ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏فَقَالَ مِثْلَ ذَلِكَ ‏ ‏فَأَنْفَذَهُ لَهَا ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏هَلْ مَعَكَ غَيْرُكَ ‏","","",""],[17298,17298,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مَسْلَمَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا قَذَفَ اللَّهُ عَزَّ وَجَلَّ فِي قَلْبِ امْرِئٍ خِطْبَةَ امْرَأَةٍ فَلَا بَأْسَ أَنْ يَنْظُرَ إِلَيْهَا ‏","","",""],[17299,17299,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ مُسْلِمٍ أَبُو عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْعَثِ الصَّنْعَانِيُّ ‏ ‏قَالَ ‏ ‏بَعَثَنَا ‏ ‏يَزِيدُ بْنُ مُعَاوِيَةَ ‏ ‏إِلَى ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فَلَمَّا قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏فُلَانٍ ‏ ‏نَسِيَ ‏ ‏زِيَادٌ ‏ ‏اسْمَهُ فَقَالَ إِنَّ النَّاسَ قَدْ صَنَعُوا مَا صَنَعُوا فَمَا ‏ ‏تَرَى فَقَالَ أَوْصَانِي خَلِيلِي ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ أَدْرَكْتَ شَيْئًا مِنْ هَذِهِ الْفِتَنِ فَاعْمَدْ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَاكْسِرْ بِهِ حَدَّ سَيْفِكَ ثُمَّ اقْعُدْ فِي بَيْتِكَ قَالَ فَإِنْ دَخَلَ عَلَيْكَ أَحَدٌ إِلَى الْبَيْتِ فَقُمْ إِلَى ‏ ‏الْمَخْدَعِ ‏ ‏فَإِنْ دَخَلَ عَلَيْكَ ‏ ‏الْمَخْدَعَ ‏ ‏فَاجْثُ ‏ ‏عَلَى رُكْبَتَيْكَ وَقُلْ ‏ ‏بُؤْ ‏ ‏بِإِثْمِي ‏ ‏وَإِثْمِكَ ‏ ‏فَتَكُونَ مِنْ أَصْحَابِ النَّارِ وَذَلِكَ جَزَاءُ الظَّالِمِينَ فَقَدْ كَسَرْتُ حَدَّ سَيْفِي وَقَعَدْتُ فِي بَيْتِي ‏","","",""],[17300,17300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ مُحَمَّدِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْيَدُ الْمُعْطِيَةُ خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[17301,17301,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أُمَيَّةُ بْنُ شِبْلٍ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَشَاطَ ‏ ‏السُّلْطَانُ ‏ ‏تَسَلَّطَ ‏ ‏الشَّيْطَانُ ‏","","",""],[17302,17302,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو وَائِلٍ صَنْعَانِيٌّ مُرَادِيٌّ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عُرْوَةَ بْنِ مُحَمَّدٍ ‏ ‏قَالَ إِذْ أُدْخِلَ عَلَيْهِ رَجُلٌ فَكَلَّمَهُ بِكَلَامٍ أَغْضَبَهُ قَالَ فَلَمَّا أَنْ غَضِبَ قَامَ ثُمَّ عَادَ إِلَيْنَا وَقَدْ تَوَضَّأَ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏عَطِيَّةَ ‏ ‏وَقَدْ كَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْغَضَبَ مِنْ الشَّيْطَانِ وَإِنَّ الشَّيْطَانَ خُلِقَ مِنْ النَّارِ وَإِنَّمَا تُطْفَأُ النَّارُ بِالْمَاءِ فَإِذَا غَضِبَ أَحَدُكُمْ فَلْيَتَوَضَّأْ ‏","","",""],[17303,17303,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏عَن ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ الْأَنْصَارِيِّ ‏ ‏ثُمَّ أَحَدِ ‏ ‏بَنِي حَارِثَةَ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ كَانَ عَامِلًا عَلَى ‏ ‏الْيَمَامَةِ ‏ ‏وَأَنَّ ‏ ‏مَرْوَانَ ‏ ‏كَتَبَ إِلَيْهِ أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏كَتَبَ إِلَيْهِ أَيُّمَا رَجُلٍ سُرِقَ مِنْهُ سَرِقَةٌ فَهُوَ أَحَقُّ بِهَا بِالثَّمَنِ حَيْثُ وَجَدَهَا قَالَ فَكَتَبْتُ إِلَى ‏ ‏مَرْوَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّهُ إِذَا كَانَ الَّذِي ‏ ‏ابْتَاعَهَا ‏ ‏مِنْ الَّذِي سَرَقَهَا غَيْرَ مُتَّهَمٍ خُيِّرَ سَيِّدُهَا فَإِنْ شَاءَ أَخَذَ الَّذِي سُرِقَ مِنْهُ بِالثَّمَنِ وَإِنْ شَاءَ اتَّبَعَ سَارِقَهُ قَالَ وَقَضَى بِذَلِكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏قَالَ سَمِعْتُ أَنَّهُ ‏ ‏يُقَالُ خُذْ مَالَكَ حَيْثُ وَجَدْتَهُ وَلَقَدْ ‏ ‏أَخْبَرَنِي ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏أَنَّ ‏ ‏أُسَيْدَ بْنَ حُضَيْرٍ الْأَنْصَارِيَّ ‏ ‏ثُمَّ أَحَدَ ‏ ‏بَنِي حَارِثَةَ ‏ ‏أَخْبَرَهُ أَنَّهُ كَانَ عَامِلًا عَلَى ‏ ‏الْيَمَامَةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏أَنَّ ‏ ‏أُسَيْدَ بْنَ حُضَيْرِ بْنِ سِمَاكٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏كَتَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏إِذَا سُرِقَ الرَّجُلُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17304,17304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏مُجَمِّعِ ابْنِ جَارِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَقْتُلُ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏الدَّجَّالَ ‏ ‏بِبَابِ ‏ ‏لُدٍّ ‏ ‏أَوْ إِلَى جَانِبِ ‏ ‏لُدٍّ ‏","","",""],[17305,17305,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي حُسَيْنٍ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ قَبْلَ أَنْ يَنْصَرِفَ وَيَثْنِيَ رِجْلَهُ مِنْ صَلَاةِ الْمَغْرِبِ وَالصُّبْحِ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ بِيَدِهِ الْخَيْرُ ‏ ‏يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كُتِبَ لَهُ بِكُلِّ وَاحِدَةٍ عَشْرُ حَسَنَاتٍ وَمُحِيَتْ عَنْهُ عَشْرُ سَيِّئَاتٍ وَرُفِعَ لَهُ عَشْرُ دَرَجَاتٍ وَكَانَتْ ‏ ‏حِرْزًا ‏ ‏مِنْ كُلِّ مَكْرُوهٍ ‏ ‏وَحِرْزًا ‏ ‏مِنْ الشَّيْطَانِ الرَّجِيمِ وَلَمْ يَحِلَّ لِذَنْبٍ يُدْرِكُهُ إِلَّا الشِّرْكَ فَكَانَ مِنْ أَفْضَلِ النَّاسِ عَمَلًا إِلَّا رَجُلًا يَفْضُلُهُ يَقُولُ أَفْضَلَ مِمَّا قَالَ ‏","","",""],[17306,17306,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الحَمِيدِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعُتُلِّ ‏ ‏الزَّنِيمِ ‏ ‏فَقَالَ ‏ ‏هُوَ الشَّدِيدُ الْخَلْقِ الْمُصَحَّحُ الْأَكُولُ الشَّرُوبُ الْوَاجِدُ لِلطَّعَامِ وَالشَّرَابِ الظَّلُومُ لِلنَّاسِ رَحْبُ ‏ ‏الْجَوْفِ ‏","","",""],[17307,17307,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الحَمِيدِ بْنُ بَهْرَامٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏سِبْطًا ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏هَلَكَ لَا ‏ ‏يُدْرَى أَيْنَ مَهْلِكُهُ وَأَنَا أَخَافُ أَنْ تَكُونَ هَذِهِ الضِّبَابُ ‏","","",""],[17308,17308,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏الْجَوَّاظُ ‏ ‏وَالْجَعْظَرِيُّ ‏ ‏وَالْعُتُلُّ ‏ ‏الزَّنِيمُ ‏ ‏قَالَ ‏ ‏هُوَ سَقَطَ مِنْ كِتَابِ أَبِي ‏","","",""],[17309,17309,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏ابْنِ غَنْمٍ الْأَشْعَرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏لَوْ اجْتَمَعْتُمَا فِي مَشُورَةٍ مَا خَالَفْتُكُمَا ‏","","",""],[17310,17310,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَهْرَ بْنَ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ غَنْمٍ ‏ ‏أَنَّ ‏ ‏الدَّارِيَّ ‏ ‏كَانَ ‏ ‏يُهْدِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّ عَامٍ ‏ ‏رَاوِيَةً ‏ ‏مِنْ خَمْرٍ فَلَمَّا كَانَ عَامَ حُرِّمَتْ فَجَاءَ ‏ ‏بِرَاوِيَةٍ ‏ ‏فَلَمَّا نَظَرَ إِلَيْهِ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ قَالَ هَلْ شَعَرْتَ أَنَّهَا قَدْ حُرِّمَتْ بَعْدَكَ قَالَ يَا رَسُولَ اللَّهِ أَفَلَا أَبِيعُهَا فَأَنْتَفِعَ بِثَمَنِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏انْطَلَقُوا إِلَى مَا حُرِّمَ عَلَيْهِمْ مِنْ شُحُومِ الْبَقَرِ وَالْغَنَمِ فَأَذَابُوهُ فَجَعَلُوهُ ثَمَنًا لَهُ فَبَاعُوا بِهِ مَا يَأْكُلُونَ وَإِنَّ الْخَمْرَ حَرَامٌ وَثَمَنَهَا حَرَامٌ وَإِنَّ الْخَمْرَ حَرَامٌ وَثَمَنَهَا حَرَامٌ وَإِنَّ الْخَمْرَ حَرَامٌ وَثَمَنَهَا حَرَامٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَهْرٌ ‏ ‏عَنِ ‏ ‏ابْنِ غَنْمٍ ‏ ‏أَنَّ ‏ ‏الدَّارِيَّ ‏ ‏كَانَ يُهْدِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَأَذَابُوهُ وَجَعَلُوهُ ‏ ‏إِهَالَةً ‏ ‏فَبَاعُوا بِهِ مَا يَأْكُلُونَ ‏","","",""],[17311,17311,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَحَلَّى أَوْ حُلِّيَ ‏ ‏بِخَزِّ ‏ ‏بَصِيصَةٍ ‏ ‏مِنْ ذَهَبٍ كُوِيَ بِهَا يَوْمَ الْقِيَامَةِ ‏","","",""],[17312,17312,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خِيَارُ عِبَادِ اللَّهِ الَّذِينَ ‏ ‏إِذَا رُءُوا ذُكِرَ اللَّهُ وَشِرَارُ عِبَادِ اللَّهِ الْمَشَّاءُونَ بِالنَّمِيمَةِ الْمُفَرِّقُونَ بَيْنَ الْأَحِبَّةِ ‏ ‏الْبَاغُونَ ‏ ‏الْبُرَآءَ ‏ ‏الْعَنَتَ ‏","","",""],[17313,17313,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَابِصَةَ بْنَ مَعْبَدٍ صَاحِبَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جِئْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ عَنْ الْبِرِّ وَالْإِثْمِ فَقَالَ جِئْتَ تَسْأَلُ عَنْ الْبِرِّ وَالْإِثْمِ فَقُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا جِئْتُكَ أَسْأَلُكَ عَنْ غَيْرِهِ فَقَالَ ‏ ‏الْبِرُّ مَا انْشَرَحَ لَهُ صَدْرُكَ وَالْإِثْمُ مَا ‏ ‏حَاكَ ‏ ‏فِي صَدْرِكَ وَإِنْ أَفْتَاكَ عَنْهُ النَّاسُ ‏","","",""],[17314,17314,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِلَالَ بْنَ يِسَافٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرِو بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏وَابِصَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا صَلَّى وَحْدَهُ خَلْفَ الصَّفِّ فَأَمَرَهُ أَنْ يُعِيدَ صَلَاتَهُ ‏","","",""],[17315,17315,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ أَبِي عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عَبْدِ اللَّهِ بْنِ مِكْرَزٍ ‏ ‏عَنْ ‏ ‏وَابِصَةَ بْنِ مَعْبَدٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُرِيدُ أَنْ لَا أَدَعَ شَيْئًا مِنْ الْبِرِّ وَالْإِثْمِ إِلَّا سَأَلْتُهُ عَنْهُ وَإِذَا عِنْدَهُ جَمْعٌ فَذَهَبْتُ ‏ ‏أَتَخَطَّى النَّاسَ فَقَالُوا إِلَيْكَ يَا ‏ ‏وَابِصَةُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْكَ يَا ‏ ‏وَابِصَةُ ‏ ‏فَقُلْتُ أَنَا ‏ ‏وَابِصَةُ ‏ ‏دَعُونِي ‏ ‏أَدْنُو ‏ ‏مِنْهُ فَإِنَّهُ مِنْ أَحَبِّ النَّاسِ إِلَيَّ أَنْ ‏ ‏أَدْنُوَ ‏ ‏مِنْهُ فَقَالَ لِي ‏ ‏ادْنُ ‏ ‏يَا ‏ ‏وَابِصَةُ ‏ ‏ادْنُ ‏ ‏يَا ‏ ‏وَابِصَةُ ‏ ‏فَدَنَوْتُ ‏ ‏مِنْهُ حَتَّى مَسَّتْ رُكْبَتِي رُكْبَتَهُ فَقَالَ يَا ‏ ‏وَابِصَةُ ‏ ‏أُخْبِرُكَ مَا جِئْتَ تَسْأَلُنِي عَنْهُ أَوْ تَسْأَلُنِي فَقُلْتُ يَا رَسُولَ اللَّهِ فَأَخْبِرْنِي قَالَ جِئْتَ تَسْأَلُنِي عَنْ الْبِرِّ وَالْإِثْمِ قُلْتُ نَعَمْ فَجَمَعَ أَصَابِعَهُ الثَّلَاثَ فَجَعَلَ ‏ ‏يَنْكُتُ ‏ ‏بِهَا فِي صَدْرِي وَيَقُولُ يَا ‏ ‏وَابِصَةُ ‏ ‏اسْتَفْتِ ‏ ‏نَفْسَكَ الْبِرُّ مَا اطْمَأَنَّ إِلَيْهِ الْقَلْبُ وَاطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَالْإِثْمُ مَا ‏ ‏حَاكَ ‏ ‏فِي الْقَلْبِ وَتَرَدَّدَ فِي الصَّدْرِ وَإِنْ أَفْتَاكَ النَّاسُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَأَفْتَوْكَ ‏","","",""],[17316,17316,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏أَقَامَنِي عَلَى ‏ ‏وَابِصَةَ بْنِ مَعْبَدٍ ‏ ‏فَقَالَ ‏ ‏حَدَّثَنِي هَذَا ‏ ‏أَنَّ رَجُلًا صَلَّى خَلْفَ الصَّفِّ وَحْدَهُ فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُعِيدَ صَلَاتَهُ ‏","","",""],[17317,17317,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ زِيَادِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عُبَيْدِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏وَابِصَةَ بْنِ مَعْبَدٍ ‏ ‏أَنَّ رَجُلًا صَلَّى خَلْفَ الصُّفُوفِ وَحْدَهُ فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُعِيدَ ‏","","",""],[17318,17318,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شِمْرِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏وَابِصَةَ بْنِ مَعْبَدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَجُلٍ صَلَّى خَلْفَ الصُّفُوفِ وَحْدَهُ فَقَالَ يُعِيدُ الصَّلَاةَ ‏","","",""],[17319,17319,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏وَابِصَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا ‏ ‏يُصَلِّي فِي الصَّفِّ وَحْدَهُ فَأَمَرَهُ أَنْ يُعِيدَ الصَّلَاةَ ‏","","",""],[17320,17320,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّبَيْرُ أَبُو عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عَبْدِ اللَّهِ بْنِ مِكْرَزٍ ‏ ‏وَلَمْ يَسْمَعْهُ مِنْهُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جُلَسَاؤُهُ وَقَدْ رَأَيْتُهُ ‏ ‏عَنْ ‏ ‏وَابِصَةَ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِي غَيْرَ مَرَّةٍ وَلَمْ يَقُلْ حَدَّثَنِي جُلَسَاؤُهُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُرِيدُ أَنْ لَا أَدَعَ شَيْئًا مِنْ الْبِرِّ وَالْإِثْمِ إِلَّا سَأَلْتُهُ عَنْهُ وَحَوْلَهُ ‏ ‏عِصَابَةٌ ‏ ‏مِنْ الْمُسْلِمِينَ يَسْتَفْتُونَهُ فَجَعَلْتُ ‏ ‏أَتَخَطَّاهُمْ قَالُوا إِلَيْكَ يَا ‏ ‏وَابِصَةُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ دَعُونِي فَأَدْنُوَ مِنْهُ فَإِنَّهُ أَحَبُّ النَّاسِ إِلَيَّ أَنْ أَدْنُوَ مِنْهُ قَالَ دَعُوا ‏ ‏وَابِصَةَ ‏ ‏ادْنُ يَا ‏ ‏وَابِصَةُ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قَالَ فَدَنَوْتُ مِنْهُ حَتَّى قَعَدْتُ بَيْنَ يَدَيْهِ فَقَالَ يَا ‏ ‏وَابِصَةُ ‏ ‏أُخْبِرُكَ أَوْ تَسْأَلُنِي قُلْتُ لَا بَلْ أَخْبِرْنِي فَقَالَ جِئْتَ تَسْأَلُنِي عَنْ الْبِرِّ وَالْإِثْمِ فَقَالَ نَعَمْ فَجَمَعَ ‏ ‏أَنَامِلَهُ ‏ ‏فَجَعَلَ ‏ ‏يَنْكُتُ ‏ ‏بِهِنَّ فِي صَدْرِي وَيَقُولُ يَا ‏ ‏وَابِصَةُ ‏ ‏اسْتَفْتِ ‏ ‏قَلْبَكَ ‏ ‏وَاسْتَفْتِ ‏ ‏نَفْسَكَ ثَلَاثَ مَرَّاتٍ ‏ ‏الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَالْإِثْمُ مَا ‏ ‏حَاكَ ‏ ‏فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ ‏","","",""],[17321,17321,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏قَالَ ‏ ‏أَرَانِي ‏ ‏زِيَادُ بْنُ أَبِي الْجَعْدِ ‏ ‏شَيْخًا ‏ ‏بِالْجَزِيرَةِ ‏ ‏يُقَالُ لَهُ ‏ ‏وَابِصَةُ بْنُ مَعْبَدٍ ‏ ‏قَالَ ‏ ‏فَأَقَامَنِي عَلَيْهِ وَقَالَ هَذَا حَدَّثَنِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا صَلَّى فِي الصَّفِّ وَحْدَهُ فَأَمَرَهُ فَأَعَادَ الصَّلَاةَ ‏ ‏قَالَ ‏ ‏وَكَانَ أَبِي يَقُولُ بِهَذَا الْحَدِيثِ ‏","","",""],[17322,17322,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏الْمُسْتَوْرِدِ ‏ ‏أَخِي ‏ ‏بَنِي فِهْرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا كَمِثْلِ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ هَذِهِ فِي ‏ ‏الْيَمِّ ‏ ‏فَلْيَنْظُرْ بِمَا يَرْجِعُ وَأَشَارَ بِالسَّبَّابَةِ ‏","","",""],[17323,17323,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏أَخَا ‏ ‏بَنِي فِهْرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ هَذِهِ فِي ‏ ‏الْيَمِّ ‏ ‏فَلْيَنْظُرْ بِمَ تَرْجِعُ ‏ ‏يَعْنِي الَّتِي ‏ ‏تَلِي ‏ ‏الْإِبْهَامَ ‏","","",""],[17324,17324,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِىِّ ‏ ‏عَنِ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ ‏ ‏خَلَّلَ ‏ ‏أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ ‏","","",""],[17325,17325,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏وَقَّاصُ بْنُ رَبِيعَةَ ‏ ‏أَنَّ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ بِرَجُلٍ مُسْلِمٍ أَكْلَةً ‏ ‏وَقَالَ ‏ ‏مَرَّةً أُكْلَةً ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُطْعِمُهُ مِثْلَهَا مِنْ جَهَنَّمَ وَمَنْ اكْتَسَى بِرَجُلٍ مُسْلِمٍ ثَوْبًا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يَكْسُوهُ مِثْلَهُ مِنْ جَهَنَّمَ وَمَنْ قَامَ بِرَجُلٍ مُسْلِمٍ مَقَامَ سُمْعَةٍ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُومُ بِهِ مَقَامَ سُمْعَةٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[17326,17326,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏أَخَا ‏ ‏بَنِي فِهْرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَاللَّهِ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ فِي ‏ ‏الْيَمِّ ‏ ‏فَلْيَنْظُرْ بِمَ تَرْجِعُ إِلَيْهِ ‏","","",""],[17327,17327,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي رَكْبٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ مَرَّ ‏ ‏بِسَخْلَةٍ ‏ ‏مَيْتَةٍ ‏ ‏مَنْبُوذَةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَرَوْنَ هَذِهِ هَانَتْ عَلَى أَهْلِهَا فَقَالُوا يَا رَسُولَ اللَّهِ مِنْ هَوَانِهَا أَلْقَوْهَا قَالَ فَوَالَّذِي نَفْسُ ‏ ‏مُحَمِّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْ هَذِهِ عَلَى أَهْلِهَا ‏","","",""],[17328,17328,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏أَخَا ‏ ‏بَنِي فِهْرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ فِي ‏ ‏الْيَمِّ ‏ ‏فَلْيَنْظُرْ بِمَ تَرْجِعُ إِلَيْهِ ‏","","",""],[17329,17329,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ هُبَيْرَةَ ‏ ‏والْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُسْتَوْرِدَ بْنَ شَدَّادٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏وَلِيَ ‏ ‏لَنَا عَمَلًا وَلَيْسَ لَهُ مَنْزِلٌ فَلْيَتَّخِذْ مَنْزِلًا أَوْ لَيْسَتْ لَهُ زَوْجَةٌ فَلْيَتَزَوَّجْ أَوْ لَيْسَ لَهُ خَادِمٌ فَلْيَتَّخِذْ خَادِمًا أَوْ لَيْسَتْ لَهُ دَابَّةٌ فَلْيَتَّخِذْ دَابَّةً وَمَنْ أَصَابَ شَيْئًا سِوَى ذَلِكَ فَهُوَ ‏ ‏غَالٌّ ‏","","",""],[17330,17330,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَابْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَمْرٍو ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْرٍو الْمَعَافِرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِىِّ ‏ ‏عَنِ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ يُخَلِّلُ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ ‏","","",""],[17331,17331,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ الْحَضْرَمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ كَانَ فِي مَجْلِسٍ فِيهِ ‏ ‏الْمُسْتَوْرِدُ بْنُ شَدَّادٍ ‏ ‏وَعَمْرُو بْنُ غَيْلَانَ بْنِ سَلَمَةَ ‏ ‏فَسَمِعَ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏وَلِيَ ‏ ‏لَنَا عَمَلًا فَلَمْ يَكُنْ لَهُ زَوْجَةً فَلْيَتَزَوَّجْ أَوْ خَادِمًا فَلْيَتَّخِذْ خَادِمًا أَوْ مَسْكَنًا فَلْيَتَّخِذْ مَسْكَنًا أَوْ دَابَّةً فَلْيَتَّخِذْ دَابَّةً فَمَنْ أَصَابَ شَيْئًا سِوَى ذَلِكَ فَهُوَ ‏ ‏غَالٌّ ‏ ‏أَوْ سَارِقٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي مَجْلِسٍ فِيهِ ‏ ‏الْمُسْتَوْرِدُ بْنُ شَدَّادٍ ‏ ‏وَعَمْرُو بْنُ غَيْلَانَ ‏ ‏فَسَمِعْتُ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ ‏ ‏وَلِيَ ‏ ‏لَنَا عَمَلًا ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏الْحَارِثِ ‏","","",""],[17332,17332,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا كَرَجُلٍ وَضَعَ إِصْبَعَهُ فِي ‏ ‏الْيَمِّ ‏ ‏ثُمَّ رَجَعَهَا قَالَ وَإِنِّي لَفِي ‏ ‏الرَّكْبِ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ عَلَى ‏ ‏سَخْلَةٍ ‏ ‏مَنْبُوذَةٍ ‏ ‏عَلَى ‏ ‏كُنَاسٍ فَقَالَ أَتَرَوْنَ هَذِهِ هَانَتْ عَلَى أَهْلِهَا فَقَالُوا مِنْ هَوَانِهَا أَلْقَوْهَا هَاهُنَا قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَلدُّنْيَا عَلَى اللَّهِ عَزَّ وَجَلَّ أَهْوَنُ مِنْ هَذِهِ عَلَى أَهْلِهَا ‏","","",""],[17333,17333,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ يَعْنِي الْمُهَلَّبِيَّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُجَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَاللَّهِ ‏ ‏مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا كَرَجُلٍ وَضَعَ إِصْبَعَهُ فِي ‏ ‏الْيَمِّ ‏ ‏ثُمَّ رَجَعَتْ إِلَيْهِ فَمَا أَخَذَ مِنْهُ قَالَ وَقَالَ ‏ ‏الْمُسْتَوْرِدُ ‏ ‏أَشْهَدُ أَنِّي كُنْتُ مَعَ ‏ ‏الرَّكْبِ ‏ ‏الَّذِينَ كَانُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ مَرَّ بِمَنْزِلِ قَوْمٍ قَدْ ارْتَحَلُوا عَنْهُ فَإِذَا سَخْلَةٌ مَطْرُوحَةٌ فَقَالَ أَتَرَوْنَ هَذِهِ هَانَتْ عَلَى أَهْلِهَا حِينَ أَلْقَوْهَا قَالُوا مِنْ هَوَانِهَا عَلَيْهِمْ أَلْقَوْهَا قَالَ فَوَاللَّهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْ هَذِهِ عَلَى أَهْلِهَا ‏","","",""],[17334,17334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمُسْتَوْرِدِ الْفِهْرِيِّ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لِعَمْرِو بْنِ الْعَاصِ ‏ ‏تَقُومُ السَّاعَةُ ‏ ‏وَالرُّومُ ‏ ‏أَكْثَرُ النَّاسِ فَقَالَ لَهُ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏أَبْصِرْ مَا تَقُولُ قَالَ أَقُولُ لَكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏إِنْ تَكُنْ قُلْتَ ذَاكَ إِنَّ فِيهِمْ لَخِصَالًا أَرْبَعًا إِنَّهُمْ لَأَسْرَعُ النَّاسِ ‏ ‏كَرَّةً ‏ ‏بَعْدَ ‏ ‏فَرَّةٍ ‏ ‏وَإِنَّهُمْ لَخَيْرُ النَّاسِ لِمِسْكِينٍ وَفَقِيرٍ وَضَعِيفٍ وَإِنَّهُمْ ‏ ‏لَأَحْلَمُ ‏ ‏النَّاسِ عِنْدَ ‏ ‏فِتْنَةٍ ‏ ‏وَالرَّابِعَةُ حَسَنَةٌ جَمِيلَةٌ وَإِنَّهُمْ لَأَمْنَعُ النَّاسِ مِنْ ظُلْمِ الْمُلُوكِ ‏","","",""],[17335,17335,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏الْمُسْتَوْرِدَ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا عِنْدَ ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏فَقُلْتُ لَهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَشَدُّ النَّاسِ عَلَيْكُمْ ‏ ‏الرُّومُ ‏ ‏وَإِنَّمَا هَلَكَتُهُمْ مَعَ السَّاعَةِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏عَمْرٌو ‏ ‏أَلَمْ ‏ ‏أَزْجُرْكَ ‏ ‏عَنْ مِثْلِ هَذَا ‏","","",""],[17336,17336,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ هَذِهِ الْأُمَّةِ مَثَلُ أَرْبَعَةِ نَفَرٍ رَجُلٌ آتَاهُ اللَّهُ مَالًا وَعِلْمًا فَهُوَ يَعْمَلُ بِهِ فِي مَالِهِ فَيُنْفِقُهُ فِي حَقِّهِ وَرَجُلٌ آتَاهُ اللَّهُ عِلْمًا وَلَمْ يُؤْتِهِ مَالًا فَهُوَ يَقُولُ لَوْ كَانَ لِي مِثْلُ مَا لِهَذَا عَمِلْتُ فِيهِ مِثْلَ الَّذِي يَعْمَلُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُمَا فِي الْأَجْرِ سَوَاءٌ وَرَجُلٌ آتَاهُ اللَّهُ مَالًا وَلَمْ يُؤْتِهِ عِلْمًا فَهُوَ ‏ ‏يَخْبِطُ ‏ ‏فِيهِ يُنْفِقُهُ فِي غَيْرِ حَقِّهِ وَرَجُلٌ لَمْ يُؤْتِهِ اللَّهُ مَالًا وَلَا عِلْمًا فَهُوَ يَقُولُ لَوْ كَانَ لِي مَالٌ مِثْلُ هَذَا عَمِلْتُ فِيهِ مِثْلَ الَّذِي يَعْمَلُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُمَا فِي ‏ ‏الْوِزْرِ ‏ ‏سَوَاءٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏وَسَمِعْتُهُ مِنْهُ يُحَدِّثُ عَنْ ‏ ‏أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏مِنْ ‏ ‏غَطَفَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ أُمَّتِي مَثَلُ أَرْبَعَةِ نَفَرٍ فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ رَجُلٌ آتَاهُ اللَّهُ مَالًا وَلَمْ يُؤْتِهِ عِلْمًا فَهُوَ يَخْبِطُ فِيهِ لَا يَصِلُ فِيهِ رَحِمًا وَلَا يُعْطِي فِيهِ حَقًّا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ الْعَدَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ ‏ ‏قَالَ ‏ ‏ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلَ هَذِهِ الْأُمَّةِ مَثَلَ أَرْبَعَةِ نَفَرٍ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا كَبْشَةَ الْأَنْمَارِيَّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ أُمَّتِي مَثَلُ أَرْبَعَةٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17337,17337,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَزْهَرَ بْنِ سَعِيدٍ الْحَرَازِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا كَبْشَةَ الْأَنْمَارِيَّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فِي أَصْحَابِهِ فَدَخَلَ ثُمَّ خَرَجَ وَقَدْ اغْتَسَلَ فَقُلْنَا يَا رَسُولَ اللَّهِ قَدْ كَانَ شَيْءٌ قَالَ ‏ ‏أَجَلْ مَرَّتْ بِي فُلَانَةُ فَوَقَعَ فِي قَلْبِي شَهْوَةُ النِّسَاءِ فَأَتَيْتُ بَعْضَ أَزْوَاجِي فَأَصَبْتُهَا فَكَذَلِكَ فَافْعَلُوا فَإِنَّهُ مِنْ ‏ ‏أَمَاثِلِ ‏ ‏أَعْمَالِكُمْ إِتْيَانُ الْحَلَالِ ‏","","",""],[17338,17338,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَوْسَطَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏تَسَارَعَ النَّاسُ إِلَى أَهْلِ ‏ ‏الْحِجْرِ ‏ ‏يَدْخُلُونَ عَلَيْهِمْ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَى فِي النَّاسِ الصَّلَاةُ جَامِعَةٌ قَالَ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُمْسِكٌ بَعِيرَهُ وَهُوَ يَقُولُ مَا تَدْخُلُونَ عَلَى قَوْمٍ غَضِبَ اللَّهُ عَلَيْهِمْ فَنَادَاهُ رَجُلٌ مِنْهُمْ نَعْجَبُ مِنْهُمْ يَا رَسُولَ اللَّهِ قَالَ أَفَلَا أُنْذِرُكُمْ بِأَعْجَبَ مِنْ ذَلِكَ ‏ ‏رَجُلٌ مِنْ أَنْفُسِكُمْ يُنْبِئُكُمْ بِمَا كَانَ قَبْلَكُمْ وَمَا هُوَ كَائِنٌ بَعْدَكُمْ فَاسْتَقِيمُوا ‏ ‏وَسَدِّدُوا ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا ‏ ‏يَعْبَأُ ‏ ‏بِعَذَابِكُمْ شَيْئًا ‏ ‏وَسَيَأْتِي قَوْمٌ لَا يَدْفَعُونَ عَنْ أَنْفُسِهِمْ بِشَيْءٍ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏تَسَارَعَ قَوْمٌ إِلَى أَهْلِ ‏ ‏الْحِجْرِ ‏ ‏يَدْخُلُونَ عَلَيْهِمْ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[17339,17339,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَادَةُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ بْنُ خَبَّابٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ثَلَاثٌ أُقْسِمُ عَلَيْهِنَّ وَأُحَدِّثُكُمْ حَدِيثًا فَاحْفَظُوهُ قَالَ فَأَمَّا الثَّلَاثُ الَّذِي أُقْسِمُ عَلَيْهِنَّ ‏ ‏فَإِنَّهُ مَا نَقَّصَ مَالَ عَبْدٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا ظُلِمَ عَبْدٌ بِمَظْلَمَةٍ فَيَصْبِرُ عَلَيْهَا إِلَّا زَادَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا عِزًّا وَلَا يَفْتَحُ عَبْدٌ بَابَ مَسْأَلَةٍ إِلَّا فَتَحَ اللَّهُ لَهُ بَابَ فَقْرٍ وَأَمَّا الَّذِي أُحَدِّثُكُمْ حَدِيثًا فَاحْفَظُوهُ فَإِنَّهُ قَالَ إِنَّمَا الدُّنْيَا لِأَرْبَعَةِ نَفَرٍ عَبْدٌ رَزَقَهُ اللَّهُ عَزَّ وَجَلَّ مَالًا وَعِلْمًا فَهُوَ يَتَّقِي فِيهِ رَبَّهُ وَيَصِلُ فِيهِ رَحِمَهُ وَيَعْلَمُ لِلَّهِ عَزَّ وَجَلَّ فِيهِ حَقَّهُ قَالَ فَهَذَا بِأَفْضَلِ الْمَنَازِلِ قَالَ وَعَبْدٌ رَزَقَهُ اللَّهُ عَزَّ وَجَلَّ عِلْمًا وَلَمْ يَرْزُقْهُ مَالًا قَالَ فَهُوَ يَقُولُ لَوْ كَانَ لِي مَالٌ عَمِلْتُ بِعَمَلِ فُلَانٍ قَالَ فَأَجْرُهُمَا سَوَاءٌ قَالَ وَعَبْدٌ رَزَقَهُ اللَّهُ مَالًا وَلَمْ يَرْزُقْهُ عِلْمًا فَهُوَ ‏ ‏يَخْبِطُ ‏ ‏فِي مَالِهِ بِغَيْرِ عِلْمٍ لَا يَتَّقِي فِيهِ رَبَّهُ عَزَّ وَجَلَّ وَلَا يَصِلُ فِيهِ رَحِمَهُ وَلَا يَعْلَمُ لِلَّهِ فِيهِ حَقَّهُ فَهَذَا بِأَخْبَثِ الْمَنَازِلِ قَالَ وَعَبْدٌ لَمْ يَرْزُقْهُ اللَّهُ مَالًا وَلَا عِلْمًا فَهُوَ يَقُولُ لَوْ كَانَ لِي مَالٌ لَعَمِلْتُ بِعَمَلِ فُلَانٍ قَالَ هِيَ نِيَّتُهُ ‏ ‏فَوِزْرُهُمَا ‏ ‏فِيهِ سَوَاءٌ ‏","","",""],[17340,17340,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ الْهَوْزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ الْأَنْمَارِيِّ ‏ ‏أَنَّهُ ‏ ‏أَتَاهُ فَقَالَ ‏ ‏أَطْرِقْنِي ‏ ‏مِنْ فَرَسِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏أَطْرَقَ ‏ ‏فَعَقَّتْ ‏ ‏لَهُ الْفَرَسُ كَانَ لَهُ كَأَجْرِ سَبْعِينَ فَرَسًا حُمِلَ عَلَيْهِ فِي سَبِيلِ اللَّهِ ‏","","",""],[17341,17341,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَسَنٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ مُرَّةَ ‏ ‏قَالَ ‏ ‏لِمُعَاوِيَةَ ‏ ‏يَا ‏ ‏مُعَاوِيَةُ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ إِمَامٍ ‏ ‏أَوْ وَالٍ ‏ ‏يُغْلِقُ بَابَهُ دُونَ ‏ ‏ذَوِي ‏ ‏الْحَاجَةِ ‏ ‏وَالْخَلَّةِ ‏ ‏وَالْمَسْكَنَةِ إِلَّا أَغْلَقَ اللَّهُ عَزَّ وَجَلَّ أَبْوَابَ السَّمَاءِ دُونَ حَاجَتِهِ ‏ ‏وَخَلَّتِهِ ‏ ‏وَمَسْكَنَتِهِ قَالَ فَجَعَلَ ‏ ‏مُعَاوِيَةُ ‏ ‏رَجُلًا عَلَى حَوَائِجِ النَّاسِ ‏","","",""],[17342,17342,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏حَدَّثَنَا ‏ ‏مَرْثَدُ بْنُ عَبْدِ اللَّهِ الْيَزَنِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الدَّيْلَمِيُّ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّا بِأَرْضٍ بَارِدَةٍ وَإِنَّا ‏ ‏لَنَسْتَعِينُ بِشَرَابٍ يُصْنَعُ لَنَا مِنْ الْقَمْحِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُسْكِرُ قَالَ نَعَمْ قَالَ فَلَا تَشْرَبُوهُ فَأَعَادَ عَلَيْهِ الثَّانِيَةَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُسْكِرُ قَالَ نَعَمْ قَالَ فَلَا تَشْرَبُوهُ قَالَ فَأَعَادَ عَلَيْهِ الثَّالِثَةَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُسْكِرُ قَالَ نَعَمْ قَالَ فَلَا تَشْرَبُوهُ قَالَ فَإِنَّهُمْ لَا يَصْبِرُونَ عَنْهُ قَالَ فَإِنْ لَمْ يَصْبِرُوا عَنْهُ فَاقْتُلْهُمْ ‏","","",""],[17343,17343,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏دَيْلَمٍ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ بَارِدَةٍ ‏ ‏نُعَالِجُ ‏ ‏بِهَا عَمَلًا شَدِيدًا وَإِنَّا نَتَّخِذُ شَرَابًا مِنْ هَذَا الْقَمْحِ ‏ ‏نَتَقَوَّى بِهِ عَلَى أَعْمَالِنَا وَعَلَى بَرْدِ بِلَادِنَا قَالَ هَلْ يُسْكِرُ قُلْتُ نَعَمْ قَالَ فَاجْتَنِبُوهُ قَالَ ثُمَّ جِئْتُ مِنْ بَيْنِ يَدَيْهِ فَقُلْتُ لَهُ مِثْلَ ذَلِكَ فَقَالَ ‏ ‏هَلْ يُسْكِرُ قُلْتُ نَعَمْ قَالَ فَاجْتَنِبُوهُ قُلْتُ إِنَّ النَّاسَ غَيْرُ تَارِكِيهِ قَالَ فَإِنْ لَمْ يَتْرُكُوهُ فَاقْتُلُوهُمْ ‏","","",""],[17344,17344,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏أَنَّ ‏ ‏دَيْلَمًا ‏ ‏أَخْبَرَهُمْ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ بَارِدَةٍ وَإِنَّا نَشْرَبُ شَرَابًا ‏ ‏نَتَقَوَّى بِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ يُسْكِرُ قَالَ نَعَمْ قَالَ ثُمَّ أَعَادَ عَلَيْهِ الْمَسْأَلَةَ قَالَ ‏ ‏هَلْ يُسْكِرُ قَالَ نَعَمْ قَالَ فَلَا تَقْرَبُوهُ قَالَ فَإِنَّهُمْ لَنْ يَصْبِرُوا قَالَ فَمَنْ لَمْ يَصْبِرْ عَنْهُ فَاقْتُلُوهُ ‏","","",""],[17345,17345,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ فَيْرُوزَ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ أَسْلَمُوا وَكَانَ فِيمَنْ أَسْلَمَ فَبَعَثُوا وَفْدَهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَيْعَتِهِمْ وَإِسْلَامِهِمْ فَقَبِلَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ فَقَالُوا يَا رَسُولَ اللَّهِ نَحْنُ مَنْ قَدْ عَرَفْتَ وَجِئْنَا مِنْ حَيْثُ قَدْ عَلِمْتَ وَأَسْلَمْنَا ‏ ‏فَمَنْ وَلِيُّنَا قَالَ اللَّهُ وَرَسُولُهُ قَالُوا حَسْبُنَا رَضِينَا ‏","","",""],[17346,17346,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ فَيْرُوزَ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏هَيْثَمٌ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ فَيْرُوزَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْكَ نَحْنُ مَنْ قَدْ عَلِمْتَ وَجِئْنَا مِنْ حَيْثُ قَدْ عَلِمْتَ ‏ ‏فَمَنْ وَلِيُّنَا قَالَ اللَّهُ وَرَسُولُهُ ‏","","",""],[17347,17347,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ضَمْرَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ فَيْرُوزَ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُنْقَضَنَّ ‏ ‏الْإِسْلَامُ ‏ ‏عُرْوَةً ‏ ‏عُرْوَةً ‏ ‏كَمَا ‏ ‏يُنْقَضُ ‏ ‏الْحَبْلُ ‏ ‏قُوَّةً قُوَّةً ‏","","",""],[17348,17348,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْجَيْشَانِيِّ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ بْنِ فَيْرُوزَ ‏ ‏أَنَّ أَبَاهُ ‏ ‏فَيْرُوزًا ‏ ‏أَدْرَكَهُ الْإِسْلَامُ وَتَحْتَهُ أُخْتَانِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَلِّقْ أَيَّهُمَا شِئْتَ ‏ ‏و قَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ عَبْدِ اللَّهِ الْمَعَافِرِيِّ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ بْنِ فَيْرُوزَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏أَدْرَكَ ‏ ‏الْإِسْلَامَ ‏","","",""],[17349,17349,"","","‏ ‏حَدَّثَنَا ‏ ‏مَوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْجَيْشَانِيِّ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ بْنِ فَيْرُوزَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَسْلَمْتُ وَعِنْدِي امْرَأَتَانِ أُخْتَانِ فَأَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُطَلِّقَ إِحْدَاهُمَا ‏","","",""],[17350,17350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَيَّاشُ بْنُ عَيَّاشٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي عَمْرٍو الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فَيْرُوزَ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّا أَصْحَابُ أَعْنَابٍ وَكَرْمٍ وَقَدْ نَزَلَ تَحْرِيمُ الْخَمْرِ فَمَا نَصْنَعُ بِهَا قَالَ ‏ ‏تَتَّخِذُونَهُ زَبِيبًا قَالَ فَنَصْنَعُ بِالزَّبِيبِ مَاذَا قَالَ تَنْقَعُونَهُ عَلَى غَدَائِكُمْ وَتَشْرَبُونَهُ عَلَى عَشَائِكُمْ وَتَنْقَعُونَهُ عَلَى عَشَائِكُمْ وَتَشْرَبُونَهُ عَلَى غَدَائِكُمْ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ نَحْنُ مَنْ قَدْ عَلِمْتَ وَنَحْنُ نُزُولٌ بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏مَنْ قَدْ عَلِمْتَ فَمَنْ وَلِيُّنَا قَالَ اللَّهُ وَرَسُولُهُ قَالَ قُلْتُ حَسْبِي يَا رَسُولَ اللَّهِ ‏","","",""],[17351,17351,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏حَدَّثَنِي ‏ ‏بَعْضُ أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ظِلَّ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ ‏ ‏صَدَقَتُهُ ‏","","",""],[17352,17352,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏فَاتِكِ بْنِ فَضَالَةَ ‏ ‏عَنْ ‏ ‏أَيْمَنَ بْنِ خُرَيْمٍ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطِيبًا فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏عَدَلَتْ شَهَادَةُ ‏ ‏الزُّورِ ‏ ‏إِشْرَاكًا بِاللَّهِ ثَلَاثًا ثُمَّ قَالَ اجْتَنِبُوا ‏ ‏الرِّجْسَ ‏ ‏مِنْ الْأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ ‏","","",""],[17353,17353,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏وَابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي حَبِيبٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي ‏ ‏رَاكِبٌ ‏ ‏غَدًا إِلَى ‏ ‏يَهُودَ ‏ ‏فَلَا تَبْدَءُوهُمْ بِالسَّلَامِ وَإِذَا سَلَّمُوا عَلَيْكُمْ فَقُولُوا وَعَلَيْكُمْ ‏","","",""],[17354,17354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَقِيلٍ زُهْرَةُ بْنُ مَعْبَدٍ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ هِشَامٍ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَهَبَتْ بِهِ أُمُّهُ ‏ ‏زَيْنَبُ ابْنَةُ حُمَيْدٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏بَايِعْهُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ صَغِيرٌ فَمَسَحَ رَأْسَهُ وَدَعَا لَهُ وَكَانَ يُضَحِّي بِالشَّاةِ الْوَاحِدَةِ عَنْ جَمِيعِ أَهْلِهِ ‏","","",""],[17355,17355,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏زُهْرَةَ بْنِ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ آخِذٌ بِيَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ وَاللَّهِ لَأَنْتَ يَا رَسُولَ اللَّهِ أَحَبُّ إِلَيَّ مِنْ كُلِّ شَيْءٍ إِلَّا نَفْسِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ عِنْدَهُ أَحَبَّ إِلَيْهِ مِنْ نَفْسِهِ قَالَ ‏ ‏عُمَرُ ‏ ‏فَلَأَنْتَ الْآنَ وَاللَّهِ أَحَبُّ إِلَيَّ مِنْ نَفْسِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآنَ يَا ‏ ‏عُمَرُ ‏","","",""],[17356,17356,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَرَأْتُ عَلَى ‏ ‏كِتَابِ أَبِي ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ جَعْفَرٍ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ رُدَيْحُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا أُبَيٍّ الْأَنْصَارِيَّ ‏ ‏وَهُوَ ‏ ‏ابْنُ أَبِي حَرَامٍ الْأَنْصَارِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْقِبْلَتَيْنِ جَمِيعًا وَعَلَيْهِ كِسَاءُ ‏ ‏خَزٍّ ‏ ‏أَغْبَرُ ‏","","",""],[17357,17357,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ مَرْوَانَ أَبُو مُحَمَّدٍ ‏ ‏سَنَةَ إِحْدَى وَثَمَانِينَ وَمِائَةٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي عَبْلَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ أُمِّ حَرَامٍ الْأَنْصَارِيَّ ‏ ‏وَقَدْ ‏ ‏صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِبْلَتَيْنِ وَعَلَيْهِ ثَوْبُ ‏ ‏خَزٍّ ‏ ‏أَغْبَرُ ‏ ‏وَأَشَارَ ‏ ‏إِبْرَاهِيمُ ‏ ‏بِيَدِهِ إِلَى ‏ ‏مَنْكِبَيْهِ ‏ ‏فَظَنَّ ‏ ‏كَثِيرٌ ‏ ‏أَنَّهُ ‏ ‏رِدَاءٌ ‏","","",""],[17358,17358,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ الْخَوْلَانِيُّ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَإِذَا ‏ ‏كَعْبٌ ‏ ‏يَقُصُّ فَقَالَ مَنْ هَذَا قَالُوا ‏ ‏كَعْبٌ ‏ ‏يَقُصُّ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ مَأْمُورٌ أَوْ مُخْتَالٌ قَالَ فَبَلَغَ ذَلِكَ ‏ ‏كَعْبًا ‏ ‏فَمَا رُئِيَ يَقُصُّ بَعْدُ ‏","","",""],[17359,17359,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَزِيدَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏بَعْضَ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ أَنَّهُ ‏ ‏قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَفْضَلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنٌ مُجَاهِدٌ بِنَفْسِهِ وَمَالِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ قَالُوا ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ ثُمَّ مُؤْمِنٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏","","",""],[17360,17360,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْكَبُوا هَذِهِ الدَّوَابَّ سَالِمَةً وَابْتَدِعُوهَا سَالِمَةً وَلَا تَتَّخِذُوهَا كَرَاسِيَّ ‏","","",""],[17361,17361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏وَعِصَامُ بْنُ خَالِدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نِمْرَانُ بْنُ مِخْمَرٍ ‏ ‏وَقَالَ ‏ ‏عِصَامُ ‏ ‏ابْنُ مُحْبِرٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ أَوْسٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاقْتُلُوهُ ‏","","",""],[17362,17362,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَسَّانَ الْكِنَانِيِّ ‏ ‏أَنَّ ‏ ‏الْحَارِثَ بْنَ مُسْلِمِ بْنِ الْحَارِثِ التَّمِيمِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّيْتَ الصُّبْحَ فَقُلْ قَبْلَ أَنْ تُكَلِّمَ أَحَدًا مِنْ النَّاسِ اللَّهُمَّ ‏ ‏أَجِرْنِي ‏ ‏مِنْ النَّارِ سَبْعَ مَرَّاتٍ فَإِنَّكَ إِنْ مِتَّ مِنْ يَوْمِكَ ذَلِكَ كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَكَ ‏ ‏جِوَارًا ‏ ‏مِنْ النَّارِ وَإِذَا صَلَّيْتَ الْمَغْرِبَ فَقُلْ قَبْلَ أَنْ تُكَلِّمَ أَحَدًا مِنْ النَّاسِ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ اللَّهُمَّ ‏ ‏أَجِرْنِي ‏ ‏مِنْ النَّارِ سَبْعَ مَرَّاتٍ فَإِنَّكَ إِنْ مِتَّ مِنْ لَيْلَتِكَ تِلْكَ كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَكَ ‏ ‏جِوَارًا ‏ ‏مِنْ النَّارِ ‏","","",""],[17363,17363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حَسَّانَ الْكِنَانِيُّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مُسْلِمِ بْنِ الْحَارِثِ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ لَهُ كِتَابًا ‏ ‏بِالْوَصَاةِ ‏ ‏لَهُ إِلَى مَنْ بَعْدِهِ مِنْ وُلَاةِ الْأَمْرِ وَخَتَمَ عَلَيْهِ ‏","","",""],[17364,17364,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فَسَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ لَا ‏ ‏تُخْزِنِي ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏مِنْ أَهْلِ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَكَانَ شَيْخًا كَبِيرًا حَسَنَ الْفَهْمِ ‏","","",""],[17365,17365,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي حَسَّانَ ‏ ‏عَنْ ‏ ‏مُخَيِّسِ بْنِ ظَبْيَانَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي جُذَامٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عَتَاهِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا لَقِيتُمْ ‏ ‏عَاشِرًا ‏ ‏فَاقْتُلُوهُ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏بِهَذَا الْحَدِيثِ وَقَصَّرَ عَنْ بَعْضِ الْإِسْنَادِ وَقَالَ ‏ ‏يَعْنِي بِذَلِكَ ‏ ‏الصَّدَقَةَ ‏ ‏يَأْخُذُهَا عَلَى غَيْرِ حَقِّهَا ‏","","",""],[17366,17366,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مُرَّةَ بْنِ كَعْبٍ ‏ ‏أَوْ ‏ ‏كَعْبِ بْنِ مُرَّةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ قَدْ حَدَّثَنِي بِهِ ‏ ‏مَنْصُورٌ ‏ ‏وَذَكَرَ ثَلَاثَةً بَيْنَهُ وَبَيْنَ ‏ ‏مُرَّةَ بْنِ كَعْبٍ ‏ ‏ثُمَّ ‏ ‏قَالَ بَعْدُ عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏أَوْ عَنْ ‏ ‏كَعْبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ اللَّيْلِ أَسْمَعُ قَالَ ‏ ‏جَوْفُ اللَّيْلِ الْآخِرِ ثُمَّ قَالَ الصَّلَاةُ مَقْبُولَةٌ حَتَّى تُصَلِّيَ الصُّبْحَ ثُمَّ لَا صَلَاةَ حَتَّى تَطْلُعَ الشَّمْسُ وَتَكُونَ قِيدَ رُمْحٍ ‏ ‏أَوْ رُمْحَيْنِ ‏ ‏ثُمَّ الصَّلَاةُ مَقْبُولَةٌ حَتَّى يَقُومَ الظِّلُّ قِيَامَ الرُّمْحِ ثُمَّ لَا صَلَاةَ حَتَّى تَزُولَ الشَّمْسُ ثُمَّ الصَّلَاةُ مَقْبُولَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ ثُمَّ لَا صَلَاةَ حَتَّى تَغِيبَ الشَّمْسُ وَإِذَا تَوَضَّأَ الْعَبْدُ فَغَسَلَ يَدَيْهِ خَرَّتْ خَطَايَاهُ مِنْ بَيْنِ يَدَيْهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَّتْ خَطَايَاهُ مِنْ وَجْهِهِ وَإِذَا غَسَلَ ذِرَاعَيْهِ خَرَّتْ خَطَايَاهُ مِنْ ذِرَاعَيْهِ وَإِذَا غَسَلَ رِجْلَيْهِ خَرَّتْ خَطَايَاهُ مِنْ رِجْلَيْهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَلَمْ يَذْكُرْ مَسْحَ الرَّأْسِ ‏ ‏وَأَيُّمَا رَجُلٍ أَعْتَقَ رَجُلًا مُسْلِمًا كَانَ فِكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عُضْوٍ مِنْ أَعْضَائِهِ عُضْوًا مِنْ أَعْضَائِهِ وَأَيُّمَا رَجُلٍ مُسْلِمٍ أَعْتَقَ امْرَأَتَيْنِ مُسْلِمَتَيْنِ كَانَتَا فِكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عُضْوَيْنِ مِنْ أَعْضَائِهِمَا عُضْوًا مِنْ أَعْضَائِهِ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً كَانَتْ فِكَاكَهَا مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عُضْوٍ مِنْ أَعْضَائِهَا عُضْوًا مِنْ أَعْضَائِهَا ‏","","",""],[17367,17367,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قُتِلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَامَ خُطَبَاءُ ‏ ‏بِإِيلِيَاءَ ‏ ‏فَقَامَ مِنْ آخِرِهِمْ رَجُلٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَالُ لَهُ ‏ ‏مُرَّةُ بْنُ كَعْبٍ ‏ ‏فَقَالَ لَوْلَا حَدِيثٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُمْتُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ فِتْنَةً ‏ ‏وَأَحْسَبُهُ قَالَ فَقَرَّبَهَا شَكَّ ‏ ‏إِسْمَاعِيلُ ‏ ‏فَمَرَّ رَجُلٌ ‏ ‏مُتَقَنِّعٌ ‏ ‏فَقَالَ هَذَا وَأَصْحَابُهُ يَوْمَئِذٍ عَلَى الْحَقِّ فَانْطَلَقْتُ فَأَخَذْتُ بِمَنْكِبِهِ وَأَقْبَلْتُ بِوَجْهِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ هَذَا قَالَ نَعَمْ قَالَ فَإِذَا هُوَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[17368,17368,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ السِّمْطِ ‏ ‏قَالَ قَالَ ‏ ‏رَجُلٌ ‏ ‏لِكَعْبِ بْنِ مُرَّةَ ‏ ‏أَوْ ‏ ‏مُرَّةَ بْنِ كَعْبٍ ‏ ‏حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ أَبُوكَ وَاحْذَرْ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا رَجُلٍ أَعْتَقَ رَجُلًا مُسْلِمًا كَانَ ‏ ‏فِكَاكَهُ ‏ ‏مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عَظْمٍ مِنْ عِظَامِهِ عَظْمًا مِنْ عِظَامِهِ وَأَيُّمَا رَجُلٍ مُسْلِمٍ أَعْتَقَ امْرَأَتَيْنِ مُسْلِمَتَيْنِ كَانَتَا ‏ ‏فِكَاكَهُ ‏ ‏مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عَظْمَيْنِ مِنْ عِظَامِهِمَا عَظْمًا مِنْ عِظَامِهِ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً كَانَتْ ‏ ‏فِكَاكَهَا ‏ ‏مِنْ النَّارِ ‏ ‏تُجْزَى بِكُلِّ عَظْمٍ مِنْ عِظَامِهَا عَظْمًا مِنْ عِظَامِهَا قَالَ وَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏قَالَ فَأَتَيْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ نَصَرَكَ وَأَعْطَاكَ وَاسْتَجَابَ لَكَ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ فَأَعْرَضَ عَنْهُ قَالَ فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ نَصَرَكَ وَأَعْطَاكَ وَاسْتَجَابَ لَكَ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُمَّ اسْقِنَا ‏ ‏غَيْثًا ‏ ‏مُغِيثًا ‏ ‏مَرِيعًا ‏ ‏طَبَقًا ‏ ‏غَدَقًا ‏ ‏غَيْرَ ‏ ‏رَائِثٍ ‏ ‏نَافِعًا غَيْرَ ضَارٍّ فَمَا كَانَتْ إِلَّا جُمُعَةً أَوْ نَحْوَهَا حَتَّى مُطِرُوا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فِي الدُّعَاءِ كَلِمَةٌ سَمِعْتُهَا مِنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏فِي ‏ ‏الِاسْتِسْقَاءِ ‏ ‏وَفِي حَدِيث ‏ ‏حَبِيبٍ ‏ ‏أَوْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ ‏ ‏جِئْتُكَ مِنْ عِنْدِ قَوْمٍ مَا يَخْطِرُ لَهُمْ فَحْلٌ وَلَا يُتَزَوَّدُ لَهُمْ رَاعٍ ‏","","",""],[17369,17369,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ السِّمْطِ ‏ ‏قَالَ قَالَ ‏ ‏لِكَعْبِ بْنِ مُرَّةَ ‏ ‏يَا ‏ ‏كَعْبُ بْنَ مُرَّةَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاحْذَرْ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ارْمُوا ‏ ‏أَهْلَ ‏ ‏صُنْعٍ ‏ ‏مَنْ بَلَغَ الْعَدُوَّ بِسَهْمٍ رَفَعَهُ اللَّهُ بِهِ دَرَجَةً قَالَ فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي النَّحَّامِ ‏ ‏يَا رَسُولَ اللَّهِ وَمَا الدَّرَجَةُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهَا لَيْسَتْ بِعَتَبَةِ أُمِّكَ وَلَكِنَّهَا بَيْنَ الدَّرَجَتَيْنِ مِائَةُ عَامٍ ‏","","",""],[17370,17370,"","","‏ ‏قَالَ ‏ ‏يَا ‏ ‏كَعْبُ بْنَ مُرَّةَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاحْذَرْ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فِكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عَظْمٍ مِنْهُ عَظْمًا مِنْهُ وَمَنْ أَعْتَقَ امْرَأَتَيْنِ ‏ ‏مُسْلِمَتَيْنِ كَانَتَا فِكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عَظْمَيْنِ مِنْهُمَا عَظْمًا مِنْهُ وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ ‏","","",""],[17371,17371,"","","‏ ‏قَالَ ‏ ‏يَا ‏ ‏كَعْبُ بْنَ مُرَّةَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاحْذَرْ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ كَانَ كَمَنْ أَعْتَقَ رَقَبَةً ‏","","",""],[17372,17372,"","","‏ ‏وَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَجَاءَهُ رَجُلٌ فَقَالَ اسْتَسْقِ اللَّهَ ‏ ‏لِمُضَرَ ‏ ‏قَالَ فَقَالَ إِنَّكَ لَجَرِيءٌ ‏ ‏أَلِمُضَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ اسْتَنْصَرْتَ اللَّهَ عَزَّ وَجَلَّ فَنَصَرَكَ وَدَعَوْتَ اللَّهَ عَزَّ وَجَلَّ فَأَجَابَكَ قَالَ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَيْهِ يَقُولُ ‏ ‏اللَّهُمَّ اسْقِنَا ‏ ‏غَيْثًا ‏ ‏مُغِيثًا ‏ ‏مَرِيعًا ‏ ‏مَرِيئًا ‏ ‏طَبَقًا ‏ ‏غَدَقًا ‏ ‏عَاجِلًا غَيْرَ ‏ ‏رَائِثٍ ‏ ‏نَافِعًا غَيْرَ ضَارٍّ قَالَ فَأُحْيُوا قَالَ فَمَا لَبِثُوا أَنْ أَتَوْهُ فَشَكَوْا إِلَيْهِ كَثْرَةَ الْمَطَرِ فَقَالُوا قَدْ تَهَدَّمَتْ الْبُيُوتُ قَالَ فَرَفَعَ يَدَيْهِ وَقَالَ اللَّهُمَّ ‏ ‏حَوَالَيْنَا ‏ ‏وَلَا عَلَيْنَا قَالَ فَجَعَلَ السَّحَابُ يَتَقَطَّعُ يَمِينًا وَشِمَالًا ‏","","",""],[17373,17373,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مُعَسْكِرِينَ مَعَ ‏ ‏مُعَاوِيَةَ ‏ ‏بَعْدَ قَتْلِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَامَ ‏ ‏كَعْبُ بْنُ مُرَّةَ الْبَهْزِيُّ ‏ ‏فَقَالَ لَوْلَا شَيْءٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُمْتُ هَذَا الْمَقَامَ فَلَمَّا سَمِعَ بِذِكْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْلَسَ النَّاسَ فَقَالَ بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ مَرَّ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏عَلَيْهِ ‏ ‏مُرَجِّلًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَخْرُجَنَّ ‏ ‏فِتْنَةٌ ‏ ‏مِنْ تَحْتِ قَدَمَيْ أَوْ مِنْ بَيْنِ رِجْلَيْ هَذَا هَذَا يَوْمَئِذٍ وَمَنْ اتَّبَعَهُ عَلَى الْهُدَى قَالَ فَقَامَ ‏ ‏ابْنُ حَوَالَةَ الْأَزْدِيُّ ‏ ‏مِنْ عِنْدِ الْمِنْبَرِ فَقَالَ إِنَّكَ لَصَاحِبُ هَذَا قَالَ نَعَمْ قَالَ وَاللَّهِ إِنِّي لَحَاضِرٌ ذَلِكَ الْمَجْلِسَ وَلَوْ عَلِمْتُ أَنَّ لِي فِي الْجَيْشِ مُصَدِّقًا كُنْتُ أَوَّلَ مَنْ تَكَلَّمَ بِهِ ‏","","",""],[17374,17374,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ يَعْنِي البُرْسَانِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏قَالَ ‏ ‏قَامَتْ خُطَبَاءُ ‏ ‏بِإِيلِيَاءَ ‏ ‏فِي إِمَارَةِ ‏ ‏مُعَاوِيَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَتَكَلَّمُوا وَكَانَ آخِرَ مَنْ تَكَلَّمَ ‏ ‏مُرَّةُ بْنُ كَعْبٍ ‏ ‏فَقَالَ لَوْلَا حَدِيثٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُمْتُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ فِتْنَةً فَقَرَّبَهَا فَمَرَّ رَجُلٌ ‏ ‏مُقَنَّعٌ ‏ ‏فَقَالَ هَذَا يَوْمَئِذٍ وَأَصْحَابُهُ عَلَى الْحَقِّ وَالْهُدَى فَقُلْتُ هَذَا يَا رَسُولَ اللَّهِ وَأَقْبَلْتُ بِوَجْهِهِ إِلَيْهِ فَقَالَ هَذَا فَإِذَا هُوَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[17375,17375,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي سَيَّارَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏الْمُتْعِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي نَخْلًا قَالَ ‏ ‏أَدِّ ‏ ‏الْعُشُورَ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ احْمِهَا لِي قَالَ فَحَمَاهَا لِي ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏احْمِ لِي جَبَلَهَا قَالَ فَحَمَى لِي جَبَلَهَا ‏","","",""],[17376,17376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّكُمْ تَقْرَءُونَ وَالْإِمَامُ يَقْرَأُ مَرَّتَيْنِ أَوْ ثَلَاثًا قَالُوا يَا رَسُولَ اللَّهِ إِنَّا لَنَفْعَلُ قَالَ فَلَا تَفْعَلُوا إِلَّا أَنْ يَقْرَأَ أَحَدُكُمْ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏","","",""],[17377,17377,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرٍ الْأَسْلَمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ حَاجِبِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ سَلَامَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ أَطْعَمْتَ وَسَقَيْتَ وَأَشْبَعْتَ وَأَرْوَيْتَ فَلَكَ الْحَمْدُ غَيْرَ مَكْفُورٍ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْكَ ‏","","",""],[17378,17378,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ رَجُلًا مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏لَمْ يَجِدْ رِيحَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا ‏","","",""],[17379,17379,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مُحَيْرِيزٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أُنَاسًا مِنْ أُمَّتِي يَشْرَبُونَ الْخَمْرَ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا ‏","","",""],[17380,17380,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَّامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ تَلَا شَيْئًا مِنْ الْقُرْآنِ ‏ ‏وَقَالَ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّةً آيًا مِنْ الْقُرْآنِ ‏ ‏قَبْلَ أَنْ يَمَسَّ مَاءً ‏","","",""],[17381,17381,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو جَعْفَرٍ عُمَيْرُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ فُضَيْلٍ ‏ ‏وَعُمَارَةُ بْنُ خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجًّا قَالَ فَرَأَيْتُهُ خَرَجَ مِنْ الْخَلَاءِ فَاتَّبَعْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏أَوْ الْقَدَحِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ حَاجَةً أَبْعَدَ فَجَلَسْتُ لَهُ بِالطَّرِيقِ حَتَّى انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ الْوَضُوءَ قَالَ فَأَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ ‏ ‏فَصَبَّ عَلَى يَدِهِ فَغَسَلَهَا ثُمَّ أَدْخَلَ يَدَهُ بِكَفِّهَا فَصَبَّ عَلَى يَدٍ وَاحِدَةٍ ثُمَّ مَسَحَ عَلَى رَأْسِهِ ثُمَّ قَبَضَ الْمَاءَ عَلَى يَدٍ وَاحِدَةٍ ثُمَّ مَسَحَ عَلَى رَأْسِهِ ثُمَّ قَبَضَ الْمَاءَ قَبْضًا بِيَدِهِ فَضَرَبَ بِهِ عَلَى ظَهْرِ قَدَمِهِ فَمَسَحَ بِيَدِهِ عَلَى قَدَمِهِ ثُمَّ جَاءَ فَصَلَّى لَنَا الظُّهْرَ ‏","","",""],[17382,17382,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَخٍ ‏ ‏بَخٍ ‏ ‏لِخَمْسٍ مَا أَثْقَلَهُنَّ فِي الْمِيزَانِ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَالْوَلَدُ الصَّالِحُ ‏ ‏يُتَوَفَّى فَيَحْتَسِبُهُ وَالِدُهُ وَقَالَ ‏ ‏بَخٍ ‏ ‏بَخٍ ‏ ‏لِخَمْسٍ مَنْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ مُسْتَيْقِنًا بِهِنَّ دَخَلَ الْجَنَّةَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَبِالْجَنَّةِ وَالنَّارِ وَبِالْبَعْثِ بَعْدَ الْمَوْتِ وَالْحِسَابِ ‏","","",""],[17383,17383,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَسْلَمَ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏هُبَيْبِ بْنِ مُغْفِلٍ الْغِفَارِيِّ ‏ ‏أَنَّهُ رَأَى ‏ ‏مُحَمَّدًا الْقُرَشِيَّ ‏ ‏قَامَ يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَنَظَرَ إِلَيْهِ ‏ ‏هُبَيْبٌ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏وَطِئَهُ ‏ ‏خُيَلَاءَ ‏ ‏وَطِئَهُ ‏ ‏فِي النَّارِ ‏","","",""],[17384,17384,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَسْلَمُ أَبُو عِمْرَانَ ‏ ‏عَنْ ‏ ‏هُبَيْبٍ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏وَطِئَ ‏ ‏عَلَى ‏ ‏إِزَارِهِ ‏ ‏خُيَلَاءَ ‏ ‏وَطِئَ ‏ ‏فِي نَارِ جَهَنَّمَ ‏","","",""],[17385,17385,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَسْلَمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏هُبَيْبَ بْنَ مُغْفِلٍ صَاحِبَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَى رَجُلًا يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏خَلْفَهُ ‏ ‏وَيَطَؤُهُ ‏ ‏خُيَلَاءَ ‏ ‏فَقَالَ سُبْحَانَ اللَّهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏وَطِئَهُ ‏ ‏مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏وَطِئَهُ ‏ ‏فِي النَّارِ ‏","","",""],[17386,17386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏حَدَّثَنَا ‏ ‏كُرَيْبُ بْنُ الْحَارِثِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ قَيْسٍ ‏ ‏أَخِي ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْ فَنَاءَ أُمَّتِي قَتْلًا فِي سَبِيلِكَ ‏ ‏بِالطَّعْنِ ‏ ‏وَالطَّاعُونِ ‏","","",""],[17387,17387,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَهِيَ ‏ ‏تَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَلُعَابُهَا يَسِيلُ بَيْنَ كَتِفَيَّ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَسَمَ لِكُلِّ إِنْسَانٍ نَصِيبَهُ مِنْ الْمِيرَاثِ فَلَا يَجُوزُ لِوَارِثٍ وَصِيَّةٌ الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏أَلَا وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوَالِيهِ ‏ ‏رَغْبَةً عَنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏وَقَالَ ‏ ‏سَعِيدٌ ‏ ‏قَالَ ‏ ‏مَطَرٌ ‏ ‏لَا يَقْبَلُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَفِي حَدِيثِهِ لَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏ ‏أَوْ ‏ ‏عَدْلٌ ‏ ‏وَلَا ‏ ‏صَرْفٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ إِنَّ ‏ ‏عَمْرَو بْنَ خَارِجَةَ ‏ ‏حَدَّثَهُمْ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَهُمْ عَلَى ‏ ‏رَاحِلَتِهِ ‏","","",""],[17388,17388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ آخِذًا ‏ ‏بِزِمَامِ ‏ ‏نَاقَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ ‏ ‏تَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَلُعَابُهَا يَسِيلُ بَيْنَ كَتِفَيَّ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ وَلَيْسَ لِوَارِثٍ وَصِيَّةٌ وَالْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ انْتَمَى إِلَى غَيْرِ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَزَادَ فِيهِ ‏ ‏هَمَّامٌ ‏ ‏بِهَذَا الْإِسْنَادِ وَلَمْ يَذْكُرْ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ غَنْمٍ ‏ ‏وَإِنِّي لَتَحْتَ ‏ ‏جِرَانِ ‏ ‏رَاحِلَتِهِ ‏ ‏وَزَادَ فِيهِ لَا يُقْبَلُ مِنْهُ ‏ ‏عَدْلٌ ‏ ‏وَلَا ‏ ‏صَرْفٌ ‏ ‏وَفِي حَدِيثِ ‏ ‏هَمَّامٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ وَقَالَ رَغْبَةً عَنْهُمْ ‏","","",""],[17389,17389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى نَاقَتِهِ وَأَنَا تَحْتَ ‏ ‏جِرَانِهَا ‏ ‏وَهِيَ ‏ ‏تَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَلُعَابُهَا يَسِيلُ بَيْنَ كَتِفَيَّ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ وَلَا وَصِيَّةَ لِوَارِثٍ وَالْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ انْتَمَى إِلَى غَيْرِ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏","","",""],[17390,17390,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ الثُّمَالِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْهَدْيِ ‏ ‏يَعْطَبُ ‏ ‏قَالَ ‏ ‏انْحَرْهُ وَاصْبُغْ نَعْلَهُ فِي دَمِهِ وَاضْرِبْ بِهِ عَلَى صَفْحَتِهِ ‏ ‏أَوْ قَالَ عَلَى جَنْبِهِ ‏ ‏وَلَا تَأْكُلَنَّ مِنْهُ شَيْئًا أَنْتَ وَلَا أَهْلُ رُفْقَتِكَ ‏","","",""],[17391,17391,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو الثُّمَالِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ أَبِي ‏ ‏هَدْيًا ‏ ‏قَالَ ‏ ‏إِذَا عَطِبَ شَيْءٌ مِنْهَا فَانْحَرْهُ ثُمَّ اضْرِبْ خُفَّهُ فِي دَمِهِ ثُمَّ اضْرِبْ بِهِ ‏ ‏صَفْحَتَهُ ‏ ‏وَلَا تَأْكُلْ أَنْتَ وَلَا أَهْلُ رُفْقَتِكَ ‏ ‏وَخَلِّ ‏ ‏بَيْنَهُ وَبَيْنَ النَّاسِ ‏","","",""],[17392,17392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ خَارِجَةَ الْخُشَنِيَّ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَهُمْ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَإِنَّ ‏ ‏رَاحِلَتَهُ ‏ ‏لَتَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَإِنَّ لُعَابَهَا يَسِيلُ بَيْنَ كَتِفَيَّ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَسَمَ لِكُلِّ إِنْسَانٍ نَصِيبَهُ مِنْ الْمِيرَاثِ فَلَا تَجُوزُ وَصِيَّةٌ لِوَارِثٍ الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏أَلَا وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏ ‏أَوْ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏","","",""],[17393,17393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِمِنًى ‏ ‏عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَإِنِّي لَتَحْتَ ‏ ‏جِرَانِ ‏ ‏نَاقَتِهِ وَهِيَ ‏ ‏تَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَلُعَابُهَا يَسِيلُ بَيْنَ كَتِفَيَّ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَسَمَ لِكُلِّ إِنْسَانٍ نَصِيبَهُ مِنْ الْمِيرَاثِ وَلَا يَجُوزُ لِوَارِثٍ وَصِيَّةٌ أَلَا وَإِنَّ الْوَلَدَ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏أَلَا وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوَالِيهِ ‏ ‏رَغْبَةً عَنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وحَدَّثَنَا ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ وَزَادَ ‏ ‏مَطَرٌ ‏ ‏فِي الْحَدِيثِ وَلَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ قَالَ ‏ ‏مَطَرٌ ‏ ‏وَلَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏ ‏أَوْ ‏ ‏عَدْلٌ ‏ ‏وَلَا ‏ ‏صَرْفٌ ‏ ‏هَذَا آخِرُ مُسْنَدِ ‏ ‏الشَّامِيِّينَ ‏","","",""],[17394,17394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏غَدَوْتُ ‏ ‏عَلَى ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ الْمُرَادِيِّ ‏ ‏أَسْأَلُهُ عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ مَا جَاءَ بِكَ قُلْتُ ابْتِغَاءَ الْعِلْمِ قَالَ أَلَا أُبَشِّرُكَ وَرَفَعَ الْحَدِيثَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَطْلُبُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17395,17395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏حَدَّثَنِي ‏ ‏زِرُّ بْنُ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏وَفَدْتُ فِي خِلَافَةِ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَإِنَّمَا حَمَلَنِي عَلَى الْوِفَادَةِ لُقِيُّ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏وَأَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَقِيتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ ‏ ‏فَقُلْتُ لَهُ هَلْ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏وَغَزَوْتُ مَعَهُ اثْنَتَيْ عَشْرَةَ غَزْوَةً ‏","","",""],[17396,17396,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ ‏ ‏فَسَأَلْتُهُ عَنْ الْمَسْحِ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏فَقَالَ كُنَّا نَكُونُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْمُرُنَا أَنْ ‏ ‏لَا نَنْزِعَ ‏ ‏خِفَافَنَا ‏ ‏ثَلَاثَةَ أَيَّامٍ إِلَّا مِنْ ‏ ‏جَنَابَةٍ ‏ ‏وَلَكِنْ مِنْ ‏ ‏غَائِطٍ ‏ ‏وَبَوْلٍ وَنَوْمٍ وَجَاءَ أَعْرَابِيٌّ ‏ ‏جَهْوَرِيُّ ‏ ‏الصَّوْتِ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏الرَّجُلُ يُحِبُّ الْقَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[17397,17397,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الْمُرَادِيِّ ‏ ‏قَالَ ‏ ‏قَالَ يَهُودِيٌّ لِصَاحِبِهِ اذْهَبْ بِنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏إِلَى هَذَا النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى نَسْأَلَهُ عَنْ هَذِهِ الْآيَةِ ‏ { ‏وَلَقَدْ آتَيْنَا ‏ ‏مُوسَى ‏ ‏تِسْعَ آيَاتٍ ‏} ‏فَقَالَ لَا تَقُلْ لَهُ نَبِيٌّ فَإِنَّهُ إِنْ سَمِعَكَ لَصَارَتْ لَهُ أَرْبَعَةُ أَعْيُنٍ فَسَأَلَاهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَسْرِقُوا وَلَا تَزْنُوا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَسْحَرُوا وَلَا تَأْكُلُوا الرِّبَا وَلَا تَمْشُوا بِبَرِيءٍ إِلَى ذِي سُلْطَانٍ لِيَقْتُلَهُ وَلَا ‏ ‏تَقْذِفُوا ‏ ‏مُحْصَنَةً ‏ ‏أَوْ قَالَ تَفِرُّوا مِنْ ‏ ‏الزَّحْفِ ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏وَأَنْتُمْ يَا ‏ ‏يَهُودُ ‏ ‏عَلَيْكُمْ خَاصَّةً أَنْ لَا تَعْتَدُوا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏تَعْدُوا ‏ ‏فِي السَّبْتِ فَقَبَّلَا يَدَهُ وَرِجْلَهُ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَدَيْهِ وَرِجْلَيْهِ ‏ ‏وَقَالَا نَشْهَدُ أَنَّكَ نَبِيٌّ قَالَ فَمَا يَمْنَعُكُمَا أَنْ تَتَّبِعَانِي قَالَا إِنَّ ‏ ‏دَاوُدَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏دَعَا أَنْ لَا يَزَالَ مِنْ ذُرِّيَّتِهِ نَبِيٌّ وَإِنَّا ‏ ‏نَخْشَى ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏إِنْ أَسْلَمْنَا أَنْ تَقْتُلَنَا ‏ ‏يَهُودُ ‏","","",""],[17398,17398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ ‏ ‏فَقَالَ مَا جَاءَ بِكَ قَالَ فَقُلْتُ جِئْتُ أَطْلُبُ الْعِلْمَ قَالَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ خَارِجٍ يَخْرُجُ مِنْ بَيْتٍ فِي طَلَبِ الْعِلْمِ إِلَّا وَضَعَتْ لَهُ الْمَلَائِكَةُ أَجْنِحَتَهَا رِضًا بِمَا يَصْنَعُ قَالَ جِئْتُ أَسْأَلُكَ عَنْ الْمَسْحِ ‏ ‏بِالْخُفَّيْنِ ‏ ‏قَالَ نَعَمْ لَقَدْ كُنْتُ فِي الْجَيْشِ الَّذِينَ بَعَثَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنَا أَنْ نَمْسَحَ عَلَى ‏ ‏الْخُفَّيْنِ ‏ ‏إِذَا نَحْنُ أَدْخَلْنَاهُمَا عَلَى طُهْرٍ ثَلَاثًا إِذَا سَافَرْنَا وَيَوْمًا وَلَيْلَةً إِذَا أَقَمْنَا وَلَا نَخْلَعَهُمَا إِلَّا مِنْ ‏ ‏جَنَابَةٍ ‏","","",""],[17399,17399,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ بِالْمَغْرِبِ بَابًا مَفْتُوحًا لِلتَّوْبَةِ مَسِيرَتُهُ سَبْعُونَ سَنَةً لَا يُغْلَقُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ نَحْوِهِ ‏","","",""],[17400,17400,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي رَوْقٍ الْهَمْدَانِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا الْغَرِيفِ ‏ ‏حَدَّثَهُمْ قَالَ قَالَ ‏ ‏صَفْوَانُ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏قَالَ ‏ ‏سِيرُوا بِاسْمِ اللَّهِ فِي سَبِيلِ اللَّهِ تُقَاتِلُونَ أَعْدَاءَ اللَّهِ لَا ‏ ‏تَغُلُّوا ‏ ‏وَلَا تَقْتُلُوا وَلِيدًا وَلِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ يَمْسَحُ عَلَى ‏ ‏خُفَّيْهِ ‏ ‏إِذَا أَدْخَلَ رِجْلَيْهِ عَلَى طُهُورٍ وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ ‏","","",""]];
